import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { z } from "zod";

const execFileAsync = promisify(execFile);
const MAX_BYTES = 65_536;
const ALLOWED_UNITS = new Set(["nginx.service", "sshd.service", "postgresql.service", "app-api.service"]);

const SECRET_PATTERNS: RegExp[] = [
  /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
  /(?:session_id|sid|auth_token)=([^;\s"']+)/gi,
  /AKIA[0-9A-Z]{16}/g,
];

function redactLine(input: string): string {
  let out = input;
  for (const re of SECRET_PATTERNS) {
    out = out.replace(re, "[REDACTED]");
  }
  return out;
}

const JournalQuerySchema = {
  unit: z.string().regex(/^[a-zA-Z0-9@_.-]+\.service$/).refine((u) => ALLOWED_UNITS.has(u), {
    message: "Unit is not in the read-only allowlist",
  }),
  sinceMinutes: z.number().int().min(1).max(1440).default(30),
  lines: z.number().int().min(1).max(250).default(50),
};

export function registerJournalTool(server: McpServer): void {
  server.tool("inspect_journal_unit", JournalQuerySchema, async ({ unit, sinceMinutes, lines }) => {
    const argv = [
      "--no-pager",
      "--quiet",
      "-o",
      "json",
      "--unit",
      unit,
      "--since",
      `-${sinceMinutes}m`,
      "-n",
      String(lines),
    ];

    const { stdout } = await execFileAsync("/usr/bin/journalctl", argv, {
      shell: false,
      timeout: 5000,
      killSignal: "SIGKILL",
      maxBuffer: MAX_BYTES * 2,
      env: { PATH: "/usr/bin:/bin", LC_ALL: "C" },
    });

    const sanitized = stdout
      .split("\n")
      .filter(Boolean)
      .map((line) => {
        try {
          const parsed = JSON.parse(line) as Record<string, unknown>;
          return JSON.stringify({
            ts: parsed.__REALTIME_TIMESTAMP,
            pid: parsed._PID,
            priority: parsed.PRIORITY,
            message: redactLine(String(parsed.MESSAGE ?? "")),
          });
        } catch {
          return redactLine(line);
        }
      })
      .join("\n");

    const buf = Buffer.from(sanitized, "utf8");
    const text =
      buf.byteLength > MAX_BYTES
        ? buf.subarray(0, MAX_BYTES).toString("utf8") + "\n...[TRUNCATED]"
        : sanitized;

    return { content: [{ type: "text", text }] };
  });
}
