use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::{Read, Seek, SeekFrom};
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Path, PathBuf};
use tokio::time::{timeout, Duration};

const MAX_OUTPUT_BYTES: usize = 32_768;
const SHB_MAGIC: u32 = 0x0A0D_0D0A;
const IDB_TYPE: u32 = 0x0000_0001;
const EPB_TYPE: u32 = 0x0000_0006;

#[derive(Deserialize)]
pub struct PcapngInspectArgs {
    pub filename: String,
    pub max_packets: usize,
}

#[derive(Serialize)]
pub struct PcapngSummary {
    pub interfaces: usize,
    pub packets_counted: usize,
    pub total_captured_bytes: u64,
    pub truncated_by_packet_cap: bool,
}

fn open_confined_pcap(root: &Path, name: &str) -> Result<std::fs::File, String> {
    if name.is_empty() || name.contains('/') || name.contains("..") || name.contains('\0') {
        return Err("Invalid PCAPng filename".into());
    }
    let canon_root = root.canonicalize().map_err(|_| "Invalid sandbox root".to_string())?;
    let candidate: PathBuf = canon_root.join(name);
    let meta = std::fs::symlink_metadata(&candidate).map_err(|_| "File not found".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() {
        return Err("Symlinks and non-regular files are rejected".into());
    }
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&candidate)
        .map_err(|e| format!("Open failed: {e}"))?;
    let canon_file = candidate.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if !canon_file.starts_with(&canon_root) {
        return Err("Workspace escape blocked".into());
    }
    Ok(file)
}

pub async fn inspect_pcapng(root: PathBuf, args: PcapngInspectArgs) -> Result<String, String> {
    let pkt_cap = args.max_packets.clamp(1, 10_000);
    let fut = tokio::task::spawn_blocking(move || -> Result<String, String> {
        let mut f = open_confined_pcap(&root, &args.filename)?;
        let mut hdr = [0u8; 8];
        let mut interfaces: usize = 0;
        let mut packets: usize = 0;
        let mut captured_bytes: u64 = 0;
        let mut hit_cap = false;

        while f.read_exact(&mut hdr).is_ok() {
            let block_type = u32::from_le_bytes([hdr[0], hdr[1], hdr[2], hdr[3]]);
            let block_len = u32::from_le_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]) as u64;
            if block_len < 12 || block_len > 16 * 1024 * 1024 || block_len % 4 != 0 {
                return Err("Malformed PCAPng block length".into());
            }
            match block_type {
                SHB_MAGIC => {
                    f.seek(SeekFrom::Current((block_len - 8) as i64)).map_err(|e| e.to_string())?;
                }
                IDB_TYPE => {
                    interfaces += 1;
                    f.seek(SeekFrom::Current((block_len - 8) as i64)).map_err(|e| e.to_string())?;
                }
                EPB_TYPE => {
                    if block_len < 32 {
                        return Err("Truncated EPB block".into());
                    }
                    let mut epb_meta = [0u8; 20];
                    f.read_exact(&mut epb_meta).map_err(|e| e.to_string())?;
                    let cap_len = u32::from_le_bytes([epb_meta[12], epb_meta[13], epb_meta[14], epb_meta[15]]) as u64;
                    captured_bytes = captured_bytes.saturating_add(cap_len);
                    packets += 1;
                    f.seek(SeekFrom::Current((block_len - 28) as i64)).map_err(|e| e.to_string())?;
                    if packets >= pkt_cap {
                        hit_cap = true;
                        break;
                    }
                }
                _ => {
                    f.seek(SeekFrom::Current((block_len - 8) as i64)).map_err(|e| e.to_string())?;
                }
            }
        }

        let summary = PcapngSummary {
            interfaces,
            packets_counted: packets,
            total_captured_bytes: captured_bytes,
            truncated_by_packet_cap: hit_cap,
        };
        let mut json = serde_json::to_string_pretty(&summary).map_err(|e| e.to_string())?;
        if json.len() > MAX_OUTPUT_BYTES {
            json.truncate(MAX_OUTPUT_BYTES);
            json.push_str("\n...[TRUNCATED]");
        }
        Ok(json)
    });

    timeout(Duration::from_secs(4), fut)
        .await
        .map_err(|_| "PCAPng inspection timed out".to_string())?
        .map_err(|e| format!("Worker join error: {e}"))?
}
