package sbomaudit

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	maxLockBytes   = 4 * 1024 * 1024
	maxOutputBytes = 32 * 1024
)

var urlCredRe = regexp.MustCompile(`(?i)(https?://)([^/@\s]+@)`)

type CargoLockArgs struct {
	Subdir string `json:"subdir"`
}

type Finding struct {
	Name   string `json:"name"`
	Ver    string `json:"version"`
	Source string `json:"source"`
	Issue  string `json:"issue"`
}

func AuditCargoLock(ctx context.Context, workspaceRoot string, args CargoLockArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	cleanSub := filepath.Clean(args.Subdir)
	if strings.HasPrefix(cleanSub, "..") || filepath.IsAbs(cleanSub) {
		return "", errors.New("subdir must be relative to workspace")
	}

	root, err := os.OpenRoot(workspaceRoot)
	if err != nil {
		return "", err
	}
	defer root.Close()

	targetRel := filepath.Join(cleanSub, "Cargo.lock")
	fi, err := root.Lstat(targetRel)
	if err != nil {
		return "", err
	}
	if fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("Cargo.lock must be a regular non-symlink file")
	}

	f, err := root.Open(targetRel)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var findings []Finding
	var curName, curVer, curSrc, curSum string
	flush := func() {
		if curName == "" {
			return
		}
		safeSrc := urlCredRe.ReplaceAllString(curSrc, "${1}[REDACTED]@")
		if curSrc == "" {
			findings = append(findings, Finding{curName, curVer, "local/path", "path_or_workspace_override"})
		} else if strings.HasPrefix(curSrc, "git+") && !strings.Contains(curSrc, "#") {
			findings = append(findings, Finding{curName, curVer, safeSrc, "unpinned_git_source"})
		} else if strings.HasPrefix(curSrc, "registry+") && len(curSum) != 64 {
			findings = append(findings, Finding{curName, curVer, safeSrc, "missing_sha256_checksum"})
		}
		curName, curVer, curSrc, curSum = "", "", "", ""
	}

	scanner := bufio.NewScanner(io.LimitReader(f, maxLockBytes))
	for scanner.Scan() {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "[[package]]" {
			flush()
			continue
		}
		kv := strings.SplitN(line, "=", 2)
		if len(kv) != 2 {
			continue
		}
		key := strings.TrimSpace(kv[0])
		val := strings.Trim(strings.TrimSpace(kv[1]), `"`)
		switch key {
		case "name":
			curName = val
		case "version":
			curVer = val
		case "source":
			curSrc = val
		case "checksum":
			curSum = val
		}
	}
	flush()
	if err := scanner.Err(); err != nil {
		return "", err
	}

	raw, err := json.MarshalIndent(map[string]any{"findings_count": len(findings), "findings": findings}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(raw) > maxOutputBytes {
		return string(raw[:maxOutputBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(raw), nil
}
