use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::{Read, Seek, SeekFrom};
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Path, PathBuf};
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 16_384;
const PT_INTERP: u32 = 3;
const PT_DYNAMIC: u32 = 2;
const PT_GNU_STACK: u32 = 0x6474_e551;
const PF_X: u32 = 0x1;

#[derive(Deserialize)]
pub struct ElfScanArgs {
    pub binary_name: String,
}

#[derive(Serialize)]
pub struct ElfStaticReport {
    pub e_type: u16,
    pub e_machine: u16,
    pub pie_or_shared: bool,
    pub has_dynamic: bool,
    pub executable_stack: bool,
    pub interpreter: Option<String>,
}

fn open_sandboxed_elf(root: &Path, name: &str) -> Result<std::fs::File, String> {
    if name.is_empty() || name.contains('/') || name.contains("..") || name.contains('\0') {
        return Err("Invalid binary filename".into());
    }
    let canon_root = root.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
    let target = canon_root.join(name);
    let meta = std::fs::symlink_metadata(&target).map_err(|_| "Target missing".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() {
        return Err("Symlinks and special files forbidden".into());
    }
    OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&target)
        .map_err(|e| format!("Open error: {e}"))
}

pub async fn scan_elf64_headers(root: PathBuf, args: ElfScanArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        let mut f = open_sandboxed_elf(&root, &args.binary_name)?;
        let mut ehdr = [0u8; 64];
        f.read_exact(&mut ehdr).map_err(|_| "File shorter than ELF64 header".to_string())?;
        if ehdr[0..4] != [0x7f, b'E', b'L', b'F'] || ehdr[4] != 2 || ehdr[5] != 1 {
            return Err("Unsupported format: expected little-endian ELF64".into());
        }

        let e_type = u16::from_le_bytes([ehdr[16], ehdr[17]]);
        let e_machine = u16::from_le_bytes([ehdr[18], ehdr[19]]);
        let e_phoff = u64::from_le_bytes(ehdr[32..40].try_into().unwrap());
        let e_phentsize = u16::from_le_bytes([ehdr[54], ehdr[55]]) as u64;
        let e_phnum = u16::from_le_bytes([ehdr[56], ehdr[57]]) as usize;
        if e_phentsize < 56 || e_phnum > 128 {
            return Err("Suspicious ELF program header count or entry size".into());
        }

        let mut has_dynamic = false;
        let mut exec_stack = false;
        let mut interp: Option<String> = None;

        for idx in 0..e_phnum {
            let off = e_phoff.checked_add((idx as u64) * e_phentsize).ok_or("Offset overflow")?;
            f.seek(SeekFrom::Start(off)).map_err(|e| e.to_string())?;
            let mut ph = [0u8; 56];
            f.read_exact(&mut ph).map_err(|e| e.to_string())?;
            let p_type = u32::from_le_bytes(ph[0..4].try_into().unwrap());
            let p_flags = u32::from_le_bytes(ph[4..8].try_into().unwrap());
            let p_offset = u64::from_le_bytes(ph[8..16].try_into().unwrap());
            let p_filesz = u64::from_le_bytes(ph[32..40].try_into().unwrap());

            match p_type {
                PT_DYNAMIC => has_dynamic = true,
                PT_GNU_STACK => exec_stack = (p_flags & PF_X) != 0,
                PT_INTERP if p_filesz > 0 && p_filesz <= 256 => {
                    f.seek(SeekFrom::Start(p_offset)).map_err(|e| e.to_string())?;
                    let mut buf = vec![0u8; p_filesz as usize];
                    f.read_exact(&mut buf).map_err(|e| e.to_string())?;
                    let trimmed = buf.split(|&b| b == 0).next().unwrap_or(&[]);
                    interp = Some(String::from_utf8_lossy(trimmed).into_owned());
                }
                _ => {}
            }
        }

        let report = ElfStaticReport {
            e_type,
            e_machine,
            pie_or_shared: e_type == 3,
            has_dynamic,
            executable_stack: exec_stack,
            interpreter: interp,
        };
        let mut out = serde_json::to_string_pretty(&report).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "ELF static scan timed out".to_string())?
        .map_err(|e| format!("Join error: {e}"))?
}
