import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

const MAX_TOKEN_LEN = 8192;
const MAX_OUTPUT_BYTES = 16_384;
const SAFE_STANDARD_CLAIMS = new Set(["iss", "aud", "exp", "nbf", "iat", "jti"]);

const JwtDiagSchema = {
  compactJwt: z.string().min(10).max(MAX_TOKEN_LEN),
  expectedIssuer: z.string().max(256).optional(),
  expectedAudience: z.string().max(256).optional(),
  clockSkewSec: z.number().int().min(0).max(300).default(30),
};

function decodeB64UrlJson(segment: string): Record<string, unknown> {
  const raw = Buffer.from(segment, "base64url").toString("utf8");
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("JWT segment did not decode to a JSON object");
  }
  return parsed as Record<string, unknown>;
}

export function registerJwtDiagnosticsTool(server: McpServer): void {
  server.tool("diagnose_jwt_hygiene", JwtDiagSchema, async (args) => {
    const parts = args.compactJwt.trim().split(".");
    if (parts.length !== 3) {
      throw new Error("Malformed JWS: expected 3 dot-separated segments (token redacted)");
    }

    let header: Record<string, unknown>;
    let claims: Record<string, unknown>;
    try {
      header = decodeB64UrlJson(parts[0]);
      claims = decodeB64UrlJson(parts[1]);
    } catch {
      throw new Error("Failed to decode JWS header or claims JSON (token redacted)");
    }

    const warnings: string[] = [];
    const alg = String(header.alg ?? "");
    if (!alg || alg.toLowerCase() === "none") {
      warnings.push("CRITICAL_ALG_NONE");
    } else if (alg.startsWith("HS")) {
      warnings.push("SYMMETRIC_HMAC_ALG_VERIFY_KEY_SEPARATION");
    }
    if (typeof header.jku === "string" || typeof header.x5u === "string") {
      warnings.push("EXTERNAL_KEY_URL_HEADER_PRESENT");
    }

    const now = Math.floor(Date.now() / 1000);
    if (typeof claims.exp !== "number") {
      warnings.push("MISSING_EXP_CLAIM");
    } else if (now > claims.exp + args.clockSkewSec) {
      warnings.push("TOKEN_EXPIRED");
    }
    if (typeof claims.nbf === "number" && now + args.clockSkewSec < claims.nbf) {
      warnings.push("TOKEN_NOT_YET_VALID");
    }
    if (args.expectedIssuer && claims.iss !== args.expectedIssuer) {
      warnings.push("ISSUER_MISMATCH");
    }
    const audList = Array.isArray(claims.aud) ? claims.aud : claims.aud ? [claims.aud] : [];
    if (args.expectedAudience && !audList.includes(args.expectedAudience)) {
      warnings.push("AUDIENCE_MISMATCH");
    }

    const sanitizedClaims: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(claims)) {
      sanitizedClaims[k] = SAFE_STANDARD_CLAIMS.has(k) ? v : "[REDACTED_CLAIM]";
    }

    const output = JSON.stringify(
      {
        header: { alg, typ: header.typ ?? null, kid: header.kid ?? null },
        claims: sanitizedClaims,
        signaturePresent: parts[2].length > 0,
        signaturePreview: "[REDACTED_SIGNATURE]",
        warnings,
      },
      null,
      2,
    );

    const buf = Buffer.from(output, "utf8");
    const text = buf.byteLength > MAX_OUTPUT_BYTES ? buf.subarray(0, MAX_OUTPUT_BYTES).toString("utf8") : output;
    return { content: [{ type: "text", text }] };
  });
