type CertInspectReport struct {
	Subject         string   `json:"subject"`
	Issuer          string   `json:"issuer"`
	NotBefore       string   `json:"not_before"`
	NotAfter        string   `json:"not_after"`
	DaysRemaining   int      `json:"days_remaining"`
	DNSNames        []string `json:"dns_names"`
	IsCA            bool     `json:"is_ca"`
	Warnings        []string `json:"warnings"`
}

func InspectPemBundle(ctx context.Context, certDir string, bundleName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if bundleName == "" || strings.ContainsAny(bundleName, "/\\") || strings.Contains(bundleName, "..") {
		return "", errors.New("invalid bundle filename")
