		if err != nil {
			return "", errors.New("malformed X.509 DER block in bundle")
		}
		var warns []string
		if now.Before(c.NotBefore) {
			warns = append(warns, "CERT_NOT_YET_VALID")
		}
		if now.After(c.NotAfter) {
			warns = append(warns, "CERT_EXPIRED")
		}
