		return "", errors.New("only LINKTYPE_ETHERNET (1) supported")
	}

	synCounts := make(map[string]int)
	var rhdr [16]byte
	buf := make([]byte, 65536)
	readPkts := 0

	for readPkts < pktLimit {
		if err := ctx.Err(); err != nil {
