use regex::Regex;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::process::Stdio;
use tokio::process::Command;
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct CosignVerifyArgs {
    pub artifact_file: String,
    pub bundle_file: String,
    pub cert_identity: String,
    pub cert_oidc_issuer: String,
}

#[derive(Serialize)]
pub struct CosignVerifyResult {
    pub verified: bool,
    pub exit_code: Option<i32>,
    pub detail: String,
}

fn check_sandboxed_file(root: &Path, filename: &str) -> Result<PathBuf, String> {
    if filename.is_empty() || filename.contains('/') || filename.contains("..") || filename.contains('\0') {
        return Err("Invalid filename".into());
    }
    let canon_root = root.canonicalize().map_err(|_| "Invalid sandbox root".to_string())?;
    let candidate = canon_root.join(filename);
    let meta = std::fs::symlink_metadata(&candidate).map_err(|_| "File does not exist".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() {
        return Err("Symlinks and non-regular files are rejected".into());
    }
    let resolved = candidate.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if resolved.parent() != Some(canon_root.as_path()) {
        return Err("Path escaped sandbox directory".into());
    }
    Ok(resolved)
}

pub async fn verify_cosign_offline(sandbox: &Path, args: CosignVerifyArgs) -> Result<String, String> {
    if !args.cert_oidc_issuer.starts_with("https://") || args.cert_identity.len() > 256 {
        return Err("Invalid OIDC issuer or certificate identity".into());
    }
    let artifact = check_sandboxed_file(sandbox, &args.artifact_file)?;
    let bundle = check_sandboxed_file(sandbox, &args.bundle_file)?;

    let mut cmd = Command::new("/usr/bin/cosign");
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", "/nonexistent")
        .arg("verify-blob")
        .arg("--offline=true")
        .arg("--bundle")
        .arg(&bundle)
        .arg("--certificate-identity")
        .arg(&args.cert_identity)
        .arg("--certificate-oidc-issuer")
        .arg(&args.cert_oidc_issuer)
        .arg("--")
        .arg(&artifact)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let output = timeout(Duration::from_secs(5), cmd.output())
        .await
        .map_err(|_| "cosign verification timed out".to_string())?
        .map_err(|e| format!("Failed to spawn cosign: {e}"))?;

    let jwt_re = Regex::new(r"eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+").unwrap();
    let combined = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let mut sanitized = jwt_re.replace_all(&combined, "[REDACTED_JWT]").into_owned();
    if sanitized.len() > MAX_OUT_BYTES {
        sanitized.truncate(MAX_OUT_BYTES);
    }

    let res = CosignVerifyResult {
        verified: output.status.success(),
        exit_code: output.status.code(),
        detail: sanitized,
    };
    serde_json::to_string_pretty(&res).map_err(|e| e.to_string())
}
