	if err := ctx.Err(); err != nil {
		return "", err
	}

	peFile, err := pe.NewFile(rawFile)
	if err != nil {
		return "", errors.New("failed to parse PE headers")
	}
	defer peFile.Close()

	rep := PeReport{
		Machine:      peFile.Machine,
		SectionCount: len(peFile.Sections),
	}

	var dllChars uint16
	switch oh := peFile.OptionalHeader.(type) {
	case *pe.OptionalHeader32:
		dllChars = oh.DllCharacteristics
	case *pe.OptionalHeader64:
		rep.IsSixtyFourBit = true
		dllChars = oh.DllCharacteristics
	}
	rep.ASLR = (dllChars & dllCharDynamicBase) != 0
	rep.HighEntropyVA = (dllChars & dllCharHighEntropyVA) != 0
	rep.DEP = (dllChars & dllCharNxCompat) != 0

	for _, sec := range peFile.Sections {
		if (sec.Characteristics&imageScnMemExecute) != 0 && (sec.Characteristics&imageScnMemWrite) != 0 {
			rep.RWXSections = append(rep.RWXSections, sec.Name)
		}
	}

	out, err := json.MarshalIndent(rep, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
