use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

const MAX_HEADER_INPUT: usize = 32_768;
const MAX_OUTPUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct HeaderGradeInput {
    pub raw_headers: String,
}

#[derive(Serialize)]
pub struct HeaderGradeReport {
    pub score: u8,
    pub findings: Vec<String>,
    pub sanitized_headers: BTreeMap<String, String>,
}

pub fn grade_security_headers(input: HeaderGradeInput) -> Result<String, String> {
    if input.raw_headers.is_empty() || input.raw_headers.len() > MAX_HEADER_INPUT {
        return Err("Header block must be between 1 and 32768 bytes".into());
    }

    let mut sanitized: BTreeMap<String, String> = BTreeMap::new();
    for line in input.raw_headers.lines().take(128) {
        if let Some((k, v)) = line.split_once(':') {
            let name = k.trim().to_ascii_lowercase();
            let val = v.trim();
            if matches!(name.as_str(), "set-cookie" | "authorization" | "proxy-authorization" | "x-api-key") {
                sanitized.insert(name, "[REDACTED]".into());
            } else {
                sanitized.insert(name, val.chars().take(512).collect());
            }
        }
    }

    let mut score: u8 = 100;
    let mut findings: Vec<String> = Vec::new();

    match sanitized.get("strict-transport-security") {
        None => {
            score = score.saturating_sub(25);
            findings.push("MISSING_HSTS".into());
        }
        Some(hsts) if !hsts.to_ascii_lowercase().contains("max-age=") => {
            score = score.saturating_sub(15);
            findings.push("HSTS_MISSING_MAX_AGE".into());
        }
        _ => {}
    }

    match sanitized.get("content-security-policy") {
        None => {
            score = score.saturating_sub(35);
            findings.push("MISSING_CSP".into());
        }
        Some(csp) => {
            let lc = csp.to_ascii_lowercase();
            if lc.contains("'unsafe-inline'") {
                score = score.saturating_sub(15);
                findings.push("CSP_UNSAFE_INLINE".into());
            }
            if lc.contains("'unsafe-eval'") {
                score = score.saturating_sub(20);
                findings.push("CSP_UNSAFE_EVAL".into());
            }
            if lc.contains("default-src *") || lc.contains("script-src *") {
                score = score.saturating_sub(20);
                findings.push("CSP_WILDCARD_SCRIPT_OR_DEFAULT".into());
            }
            if !lc.contains("frame-ancestors") {
                score = score.saturating_sub(10);
                findings.push("CSP_MISSING_FRAME_ANCESTORS".into());
            }
        }
    }

    if sanitized.get("x-content-type-options").map(|s| s.to_ascii_lowercase()).as_deref() != Some("nosniff") {
        score = score.saturating_sub(10);
        findings.push("MISSING_X_CONTENT_TYPE_NOSNIFF".into());
    }

    let report = HeaderGradeReport {
        score,
        findings,
        sanitized_headers: sanitized,
    };
    let mut out = serde_json::to_string_pretty(&report).map_err(|e| e.to_string())?;
    if out.len() > MAX_OUTPUT_BYTES {
        out.truncate(MAX_OUTPUT_BYTES);
    }
    Ok(out)
}
