    }
    Ok(resolved)
}

pub fn query_proxy_sqlite(sandbox: &Path, q: ProxyLogQuery) -> Result<String, String> {
    if q.domain_suffix.contains('%') || q.domain_suffix.contains('_') {
        return Err("Wildcard metacharacters disallowed in domain_suffix".into());
    }
    let db_path = verify_confined_sqlite(sandbox, &q.db_name)?;
    let uri = format!("file:{}?mode=ro", db_path.display());
    let flags = OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_URI | OpenFlags::SQLITE_OPEN_NO_MUTEX;
    let conn = Connection::open_with_flags(uri, flags).map_err(|e| e.to_string())?;
    conn.busy_timeout(Duration::from_millis(800)).map_err(|e| e.to_string())?;

    let deadline = Instant::now() + Duration::from_secs(3);
    conn.progress_handler(1000, Some(move || Instant::now() > deadline));

    let row_cap = q.limit.clamp(1, 250);
    let suffix_pattern = format!("%{}", q.domain_suffix);
    let redact_re = Regex::new(r"(?i)(bearer\s+[a-z0-9._~+/=-]+|basic\s+[a-z0-9+/=]+)").unwrap();

    let mut stmt = conn
        .prepare(
            "SELECT ts, client_ip, host, status, note FROM proxy_logs \
             WHERE client_ip = ?1 AND host LIKE ?2 ORDER BY ts DESC LIMIT ?3",
        )
        .map_err(|e| e.to_string())?;

    let iter = stmt
        .query_map(params![q.client_ip, suffix_pattern, row_cap], |row| {
            let raw_note: String = row.get::<_, Option<String>>(4)?.unwrap_or_default();
            Ok(ProxyEvent {
                ts: row.get(0)?,
                client_ip: row.get(1)?,
                host: row.get(2)?,
                status: row.get(3)?,
                user_agent_or_note: redact_re.replace_all(&raw_note, "[REDACTED]").into_owned(),
            })
        })
        .map_err(|e| e.to_string())?;

    let mut events: Vec<ProxyEvent> = Vec::new();
    for item in iter {
        events.push(item.map_err(|e| e.to_string())?);
    }

    let mut out = serde_json::to_string_pretty(&events).map_err(|e| e.to_string())?;
    if out.len() > MAX_OUT_BYTES {
        out.truncate(MAX_OUT_BYTES);
        out.push_str("\n...[TRUNCATED]");
    }
    Ok(out)
}
