import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { createReadStream } from "node:fs";
import { lstat, realpath } from "node:fs/promises";
import path from "node:path";
import { createGunzip } from "node:zlib";
import { z } from "zod";

const MAX_COMPRESSED_BYTES = 2 * 1024 * 1024;
const MAX_DECOMPRESSED_BYTES = 8 * 1024 * 1024;
const MAX_OUT_BYTES = 32_768;
const AWS_CRED_RE = /(?:AKIA|ASIA)[0-9A-Z]{16}|(?<="sessionToken":")[^"]+/g;

const GzTrailSchema = {
  archiveName: z.string().regex(/^[a-zA-Z0-9_.-]+\.json\.gz$/),
  errorCode: z.string().regex(/^[A-Za-z0-9.*_-]{2,64}$/).optional(),
  maxEvents: z.number().int().min(1).max(100).default(25),
};

async function gunzipBounded(filePath: string, timeoutMs: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let total = 0;
    const src = createReadStream(filePath);
    const gunzip = createGunzip({ maxOutputLength: MAX_DECOMPRESSED_BYTES });
    const timer = setTimeout(() => {
      src.destroy();
      gunzip.destroy(new Error("Decompression timed out"));
    }, timeoutMs);

    gunzip.on("data", (chunk: Buffer) => {
      total += chunk.length;
      if (total > MAX_DECOMPRESSED_BYTES) {
        src.destroy();
        gunzip.destroy(new Error("Decompressed payload exceeds 8 MiB safety cap"));
        return;
      }
      chunks.push(chunk);
    });
    gunzip.on("end", () => {
      clearTimeout(timer);
      resolve(Buffer.concat(chunks).toString("utf8"));
    });
    gunzip.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
    src.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
    src.pipe(gunzip);
  });
}

export function registerCloudTrailGzTool(server: McpServer, trailDir = "/srv/sandbox/trails"): void {
  server.tool("inspect_cloudtrail_gz", GzTrailSchema, async ({ archiveName, errorCode, maxEvents }) => {
    const canonRoot = await realpath(trailDir);
    const candidate = path.join(canonRoot, archiveName);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_COMPRESSED_BYTES) {
      throw new Error("Invalid, symlinked, or oversized archive file");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonRoot) {
      throw new Error("Archive path escaped sandbox root");
    }

    const rawJson = await gunzipBounded(resolved, 4000);
    const doc = JSON.parse(rawJson) as { Records?: Array<Record<string, any>> };
    const filtered = (doc.Records ?? [])
      .filter((r) => (!errorCode ? Boolean(r.errorCode) : r.errorCode === errorCode))
      .slice(0, maxEvents)
      .map((r) => ({
        eventTime: r.eventTime,
        eventSource: r.eventSource,
        eventName: r.eventName,
        errorCode: r.errorCode ?? null,
        sourceIPAddress: r.sourceIPAddress,
        arn: String(r.userIdentity?.arn ?? "").replace(AWS_CRED_RE, "[REDACTED]"),
      }));

    const serialized = JSON.stringify({ matched: filtered.length, events: filtered }, null, 2).replace(
      AWS_CRED_RE,
      "[REDACTED]",
    );
    const buf = Buffer.from(serialized, "utf8");
    const text =
      buf.byteLength > MAX_OUT_BYTES
        ? buf.subarray(0, MAX_OUT_BYTES).toString("utf8") + "\n...[TRUNCATED]"
        : serialized;
    return { content: [{ type: "text", text }] };
  });
