import os
import re
import time
from datetime import datetime, timezone
from pathlib import Path
from cryptography import x509
from mcp.server.fastmcp import FastMCP
from pydantic import BaseModel, Field

mcp = FastMCP("x509-chain-inspector")
CERT_ROOT = Path("/srv/sandbox/certs").resolve()
MAX_PEM_BYTES = 524_288
MAX_OUT_BYTES = 32_768
PRIV_BLOCK_RE = re.compile(rb"-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----")

class X509InspectArgs(BaseModel):
