    if candidate.is_symlink():
        raise ValueError("Symlink certificate files are forbidden")
    resolved = candidate.resolve(strict=True)
    if resolved.parent != CERT_ROOT or not resolved.is_file():
        raise ValueError("Certificate path escapes sandbox")
    fd = os.open(str(resolved), os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        st = os.fstat(fd)
        if st.st_size > MAX_PEM_BYTES:
            raise ValueError("PEM bundle exceeds 512 KiB cap")
        return os.read(fd, MAX_PEM_BYTES)
    finally:
        os.close(fd)

