    host = hostname.lower()
    for pat in dns_names:
        p = pat.lower()
        if p == host:
            return True
        if p.startswith("*.") and host.count(".") == p.count(".") and fnmatch.fnmatch(host, p):
            return True
    return False

@mcp.tool()
def inspect_x509_san_and_chain(args: X509InspectArgs) -> str:
    deadline = time.monotonic() + 2.5
    raw_pem = _load_confined_pem(args.pem_file)
    priv_blocks = len(PRIV_BLOCK_RE.findall(raw_pem))
    scrubbed_pem = PRIV_BLOCK_RE.sub(b"", raw_pem)

    certs = x509.load_pem_x509_certificates(scrubbed_pem)
    if not certs:
        raise ValueError("No X.509 certificates found in PEM file")

    now = datetime.now(timezone.utc)
    chain_items: list[dict[str, object]] = []
    chain_order_ok = True

    for idx, cert in enumerate(certs):
        if time.monotonic() > deadline:
            raise TimeoutError("X.509 inspection timed out")
        try:
            san_ext = cert.extensions.get_extension_for_class(x509.SubjectAlternativeName)
            dns_sans = san_ext.value.get_values_for_type(x509.DNSName)
        except x509.ExtensionNotFound:
            dns_sans = []

        sig_alg = cert.signature_hash_algorithm.name.lower() if cert.signature_hash_algorithm else "none"
        warns: list[str] = []
        if sig_alg in ("md5", "sha1"):
            warns.append(f"WEAK_SIGNATURE_HASH_{sig_alg.upper()}")
        if now > cert.not_valid_after_utc:
            warns.append("EXPIRED")
        if idx == 0 and args.expected_hostname and not _matches_dns_san(args.expected_hostname, dns_sans):
            warns.append("LEAF_SAN_HOSTNAME_MISMATCH")
        if idx + 1 < len(certs) and cert.issuer != certs[idx + 1].subject:
            chain_order_ok = False

        chain_items.append({
            "position": idx,
            "subject": cert.subject.rfc4514_string(),
            "issuer": cert.issuer.rfc4514_string(),
            "not_after": cert.not_valid_after_utc.isoformat(),
            "dns_sans": dns_sans[:50],
            "warnings": warns,
        })

    out = json.dumps(
        {
            "private_keys_redacted": priv_blocks,
            "chain_issuer_order_valid": chain_order_ok,
            "certificates": chain_items,
        },
        indent=2,
    )
    return out.encode("utf-8")[:MAX_OUT_BYTES].decode("utf-8", errors="ignore")
