package journalmcp

import (
	"bytes"
	"context"
	"errors"
	"os/exec"
	"regexp"
	"strconv"
	"time"
)

const maxJournalBytes = 32 * 1024

var (
	cursorRe = regexp.MustCompile(`^[a-zA-Z0-9=;_-]{10,256}$`)
	secretRe = regexp.MustCompile(`(?i)(bearer\s+[a-z0-9._~+/=-]+|(?:password|passwd|api_key|secret)=[^\s"'&]+)`)
)

type JournalPriorityArgs struct {
	MaxPriority int    `json:"max_priority"`
	AfterCursor string `json:"after_cursor"`
	MaxLines    int    `json:"max_lines"`
}

type cappedBuffer struct {
	buf bytes.Buffer
	max int
}

func (c *cappedBuffer) Write(p []byte) (int, error) {
	origLen := len(p)
	rem := c.max - c.buf.Len()
	if rem > 0 {
		if len(p) > rem {
			p = p[:rem]
		}
		c.buf.Write(p)
	}
	return origLen, nil
}

func ReadJournalByPriority(ctx context.Context, args JournalPriorityArgs) (string, error) {
	if args.MaxPriority < 0 || args.MaxPriority > 7 {
		return "", errors.New("max_priority must be between 0 and 7")
	}
	if args.MaxLines <= 0 || args.MaxLines > 200 {
		args.MaxLines = 50
	}

	argv := []string{
		"--no-pager",
		"--quiet",
		"-o",
		"short-iso",
		"-p",
		strconv.Itoa(args.MaxPriority),
		"-n",
		strconv.Itoa(args.MaxLines),
	}
	if args.AfterCursor != "" {
		if !cursorRe.MatchString(args.AfterCursor) {
			return "", errors.New("malformed journald cursor")
		}
		argv = append(argv, "--after-cursor="+args.AfterCursor)
	}

	ctx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "/usr/bin/journalctl", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "LC_ALL=C"}
	outBuf := &cappedBuffer{max: maxJournalBytes * 2}
	cmd.Stdout = outBuf

	if err := cmd.Run(); err != nil {
		return "", errors.New("journalctl query failed or timed out")
	}

	sanitized := secretRe.ReplaceAll(outBuf.buf.Bytes(), []byte("[REDACTED]"))
	if len(sanitized) > maxJournalBytes {
		return string(sanitized[:maxJournalBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(sanitized), nil
}
