import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { lstat, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_PCAP_BYTES = 8 * 1024 * 1024;
const MAX_OUT_BYTES = 32_768;

const PureDnsPcapSchema = {
  pcapFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.pcap$/),
  maxPackets: z.number().int().min(1).max(5000).default(1500),
};

function decodeDnsQname(dnsBuf: Buffer, startOffset: number): string | null {
  const labels: string[] = [];
  let pos = startOffset;
  let hops = 0;
  let totalChars = 0;

  while (pos < dnsBuf.length) {
    const len = dnsBuf[pos];
    if (len === 0) return labels.join(".");
    if ((len & 0xc0) === 0xc0) {
      if (pos + 1 >= dnsBuf.length || ++hops > 4) return null;
      const ptr = ((len & 0x3f) << 8) | dnsBuf[pos + 1];
      if (ptr >= pos || ptr >= dnsBuf.length) return null;
      pos = ptr;
      continue;
    }
    if (len > 63 || pos + 1 + len > dnsBuf.length) return null;
    const lbl = dnsBuf.subarray(pos + 1, pos + 1 + len).toString("ascii").replace(/[^a-zA-Z0-9_.-]/g, "?");
    totalChars += lbl.length + 1;
    if (totalChars > 255) return null;
    labels.push(lbl);
    pos += 1 + len;
  }
  return null;
}

export function registerPureDnsPcapTool(server: McpServer, pcapDir = "/var/sandbox/pcaps"): void {
  server.tool("parse_pcap_dns_pure", PureDnsPcapSchema, async ({ pcapFile, maxPackets }) => {
    const canonDir = await realpath(pcapDir);
    const candidate = path.join(canonDir, pcapFile);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_PCAP_BYTES) {
      throw new Error("PCAP file is symlinked, missing, or exceeds 8 MiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("PCAP path escaped sandbox directory");
    }

    const raw = await readFile(resolved, { signal: AbortSignal.timeout(3000) });
    if (raw.length < 24) throw new Error("Truncated PCAP header");
    const magic = raw.readUInt32LE(0);
    const le = magic === 0xa1b2c3d4 || magic === 0xa1b23c4d;
    if (!le && magic !== 0xd4c3b2a1 && magic !== 0x4d3cb2a1) {
      throw new Error("Unsupported PCAP magic");
    }

    let offset = 24;
    let pkts = 0;
    const counts = new Map<string, number>();

    while (offset + 16 <= raw.length && pkts < maxPackets) {
      const inclLen = le ? raw.readUInt32LE(offset + 8) : raw.readUInt32BE(offset + 8);
      offset += 16;
      if (inclLen > 65535 || offset + inclLen > raw.length) break;
      const frame = raw.subarray(offset, offset + inclLen);
      offset += inclLen;
      pkts++;

      if (frame.length >= 42 && frame.readUInt16BE(12) === 0x0800 && frame[23] === 17) {
        const ihl = (frame[14] & 0x0f) * 4;
        if (ihl >= 20 && frame.length >= 14 + ihl + 20) {
          const srcPort = frame.readUInt16BE(14 + ihl);
          const dstPort = frame.readUInt16BE(14 + ihl + 2);
