              if (qname) counts.set(qname, (counts.get(qname) ?? 0) + 1);
            }
          }
        }
      }
    }

    const top = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 50);
    const out = JSON.stringify({ packetsScanned: pkts, topQueries: top }, null, 2);
    const buf = Buffer.from(out, "utf8");
    const text = buf.byteLength > MAX_OUT_BYTES ? buf.subarray(0, MAX_OUT_BYTES).toString("utf8") : out;
    return { content: [{ type: "text", text }] };
  });
}
