package pcaparp

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

const maxOutBytes = 16 * 1024

type ArpAuditArgs struct {
	PcapName   string `json:"pcap_name"`
	MaxPackets int    `json:"max_packets"`
}

func DetectArpConflicts(ctx context.Context, sandboxDir string, args ArpAuditArgs) (string, error) {
	if args.PcapName == "" || strings.ContainsAny(args.PcapName, "/\\") || strings.Contains(args.PcapName, "..") {
		return "", errors.New("invalid pcap filename")
	}
	if args.MaxPackets <= 0 || args.MaxPackets > 5000 {
		args.MaxPackets = 2000
	}

	root, err := os.OpenRoot(sandboxDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.PcapName)
	if err != nil {
		return "", err
	}
	if fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("symlinks and non-regular files are rejected")
	}

	canonRoot, err := filepath.EvalSymlinks(sandboxDir)
	if err != nil {
		return "", err
	}
	canonFile, err := filepath.EvalSymlinks(filepath.Join(canonRoot, args.PcapName))
	if err != nil || filepath.Dir(canonFile) != canonRoot {
		return "", errors.New("capture path escaped sandbox")
	}

	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	argv := []string{
		"-n",
		"-r", canonFile,
		"-c", strconv.Itoa(args.MaxPackets),
		"-Y", "arp.opcode == 2",
		"-T", "fields",
		"-E", "separator=\t",
		"-e", "arp.src.proto_ipv4",
		"-e", "arp.src.hw_mac",
	}

	cmd := exec.CommandContext(ctx, "/usr/bin/tshark", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "HOME=/nonexistent"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("tshark ARP scan failed or timed out")
	}

	ipToMacs := make(map[string]map[string]struct{})
	for _, line := range strings.Split(stdout.String(), "\n") {
		parts := strings.Split(strings.TrimSpace(line), "\t")
		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
			continue
		}
		if ipToMacs[parts[0]] == nil {
			ipToMacs[parts[0]] = make(map[string]struct{})
		}
		ipToMacs[parts[0]][strings.ToLower(parts[1])] = struct{}{}
	}

	conflicts := make(map[string][]string)
	for ip, macSet := range ipToMacs {
		if len(macSet) > 1 {
			var macs []string
			for m := range macSet {
				macs = append(macs, m)
			}
			sort.Strings(macs)
			conflicts[ip] = macs
		}
	}

	out, err := json.MarshalIndent(map[string]any{"conflict_count": len(conflicts), "conflicts": conflicts}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
