		} `json:"checksums"`
	} `json:"packages"`
}

func AuditSpdxJson(ctx context.Context, sbomDir string, fileName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(fileName, ".spdx.json") || strings.ContainsAny(fileName, "/\\") || strings.Contains(fileName, "..") {
		return "", errors.New("invalid SPDX JSON filename")
	}

	root, err := os.OpenRoot(sbomDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(fileName)
	if err != nil {
		return "", err
	}
	if fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("symlinks and non-regular files are forbidden")
	}

	f, err := root.Open(fileName)
	if err != nil {
		return "", err
	}
	defer f.Close()

	raw, err := io.ReadAll(io.LimitReader(f, maxSpdxBytes))
	if err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}

	var doc spdxDoc
	if err := json.Unmarshal(raw, &doc); err != nil {
		return "", errors.New("failed to parse SPDX JSON")
	}
	if !strings.HasPrefix(doc.SpdxVersion, "SPDX-") {
		return "", errors.New("missing SPDX- version prefix")
	}

	type gap struct {
		Package  string   `json:"package"`
		Version  string   `json:"version"`
		Download string   `json:"download"`
		Issues   []string `json:"issues"`
	}
	var gaps []gap

	for _, p := range doc.Packages {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		var issues []string
		if p.DownloadLocation == "" || p.DownloadLocation == "NOASSERTION" || p.DownloadLocation == "NONE" {
			issues = append(issues, "UNVERIFIED_DOWNLOAD_LOCATION")
		}
