            continue;
        }
        if let Some(stripped) = clean.strip_suffix('\\') {
            current.push_str(stripped.trim());
            current.push(' ');
        } else {
            current.push_str(clean);
            logical_lines.push(std::mem::take(&mut current));
        }
    }

    let mut issues: Vec<ReqIssue> = Vec::new();
    for item in logical_lines {
        let safe_item = auth_re.replace_all(&item, "${1}[REDACTED]@").into_owned();
        if safe_item.starts_with("--extra-index-url") || safe_item.starts_with("--trusted-host") {
            issues.push(ReqIssue { entry: safe_item, reason: "UNSAFE_INDEX_FLAG".into() });
            continue;
        }
        if safe_item.starts_with('-') {
            continue;
        }
        if safe_item.contains("git+") || safe_item.contains(" @ http") {
            issues.push(ReqIssue { entry: safe_item, reason: "DIRECT_URL_OR_VCS_DEPENDENCY".into() });
            continue;
        }
        if !safe_item.contains("==") {
            issues.push(ReqIssue { entry: safe_item, reason: "UNPINNED_VERSION_SPECIFIER".into() });
        } else if !hash_re.is_match(&safe_item) {
            issues.push(ReqIssue { entry: safe_item, reason: "MISSING_SHA256_HASH".into() });
        }
    }

    let mut out = serde_json::to_string_pretty(&issues).map_err(|e| e.to_string())?;
    if out.len() > MAX_OUT_BYTES {
        out.truncate(MAX_OUT_BYTES);
    }
    Ok(out)
}
