use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Path, PathBuf};
use tokio::time::{timeout, Duration};

const MAX_WASM_BYTES: usize = 8 * 1024 * 1024;
const MAX_OUT_BYTES: usize = 32_768;

#[derive(Deserialize)]
pub struct WasmScanArgs {
    pub wasm_file: String,
}

#[derive(Serialize)]
pub struct WasmImportEntry {
    pub module: String,
    pub field: String,
    pub sensitive_capability: bool,
}

fn read_uleb128(buf: &[u8], pos: &mut usize) -> Result<u32, String> {
    let mut result: u32 = 0;
    let mut shift: u32 = 0;
    for _ in 0..5 {
        if *pos >= buf.len() {
            return Err("Truncated LEB128 integer".into());
        }
        let byte = buf[*pos];
        *pos += 1;
        result |= ((byte & 0x7f) as u32) << shift;
        if (byte & 0x80) == 0 {
            return Ok(result);
        }
        shift += 7;
    }
    Err("LEB128 exceeds 5 bytes".into())
}

fn read_wasm_name(buf: &[u8], pos: &mut usize) -> Result<String, String> {
    let len = read_uleb128(buf, pos)? as usize;
    if len > 256 || *pos + len > buf.len() {
        return Err("Invalid WASM UTF-8 name length".into());
    }
    let s = std::str::from_utf8(&buf[*pos..*pos + len]).map_err(|_| "Invalid UTF-8 in import".to_string())?;
    *pos += len;
    Ok(s.to_string())
}

pub async fn scan_wasm_imports(sandbox: PathBuf, args: WasmScanArgs) -> Result<String, String> {
    let task = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.wasm_file.ends_with(".wasm") || args.wasm_file.contains('/') || args.wasm_file.contains("..") {
            return Err("Invalid .wasm filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.wasm_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "WASM file missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_WASM_BYTES as u64 {
            return Err("Symlinked, non-regular, or oversized WASM binary".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut data: Vec<u8> = Vec::new();
        f.read_to_end(&mut data).map_err(|e| e.to_string())?;
        if data.len() < 8 || data[0..8] != [0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00] {
            return Err("Invalid WASM v1 header".into());
        }

        let mut pos: usize = 8;
        let mut imports: Vec<WasmImportEntry> = Vec::new();

        while pos < data.len() {
            let sec_id = data[pos];
            pos += 1;
            let sec_len = read_uleb128(&data, &mut pos)? as usize;
            if pos + sec_len > data.len() {
                return Err("Section length exceeds binary bounds".into());
            }
            if sec_id == 2 {
                let mut ipos = pos;
                let count = read_uleb128(&data, &mut ipos)?.min(1000);
                for _ in 0..count {
                    let module = read_wasm_name(&data, &mut ipos)?;
                    let field = read_wasm_name(&data, &mut ipos)?;
                    if ipos >= pos + sec_len {
                        break;
                    }
                    let kind = data[ipos];
                    ipos += 1;
                    match kind {
                        0 => { let _ = read_uleb128(&data, &mut ipos)?; }
                        _ => break,
                    }
                    let sensitive = module.contains("wasi")
                        && (field.starts_with("path_") || field.starts_with("sock_") || field == "fd_write");
                    imports.push(WasmImportEntry { module, field, sensitive_capability: sensitive });
                }
            }
            pos += sec_len;
        }

        let mut out = serde_json::to_string_pretty(&imports).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(2), task)
        .await
        .map_err(|_| "WASM scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
