package edverify

import (
	"context"
	"crypto/ed25519"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"os"
	"strings"
	"time"
)

const maxManifestBytes = 4 * 1024 * 1024

var pinnedPubKeys = map[string]string{
	"release-2026-q4": "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
}

type EdVerifyArgs struct {
	ManifestFile string `json:"manifest_file"`
	SigHex       string `json:"sig_hex"`
	KeyID        string `json:"key_id"`
}

func VerifyDetachedEd25519(ctx context.Context, releaseDir string, args EdVerifyArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if args.ManifestFile == "" || strings.ContainsAny(args.ManifestFile, "/\\") || strings.Contains(args.ManifestFile, "..") {
		return "", errors.New("invalid manifest filename")
	}
	pubHex, ok := pinnedPubKeys[args.KeyID]
	if !ok {
		return "", errors.New("unknown or unpinned key_id")
	}
	pubBytes, err := hex.DecodeString(pubHex)
	if err != nil || len(pubBytes) != ed25519.PublicKeySize {
		return "", errors.New("invalid pinned public key configuration")
	}

	sigBytes, err := hex.DecodeString(strings.TrimSpace(args.SigHex))
	if err != nil || len(sigBytes) != ed25519.SignatureSize {
		return "", errors.New("signature must be 64-byte hex-encoded Ed25519 signature (input redacted)")
	}

	root, err := os.OpenRoot(releaseDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.ManifestFile)
	if err != nil {
		return "", err
	}
	if fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxManifestBytes {
		return "", errors.New("manifest file is symlinked, non-regular, or exceeds 4 MiB")
	}

	f, err := root.Open(args.ManifestFile)
	if err != nil {
		return "", err
	}
	defer f.Close()

	if err := ctx.Err(); err != nil {
		return "", err
	}
	msg, err := io.ReadAll(io.LimitReader(f, maxManifestBytes))
	if err != nil {
		return "", err
	}

	valid := ed25519.Verify(ed25519.PublicKey(pubBytes), msg, sigBytes)
	out, err := json.MarshalIndent(map[string]any{
		"manifest":  args.ManifestFile,
		"key_id":    args.KeyID,
		"verified":  valid,
		"signature": "[REDACTED]",
	}, "", "  ")
	if err != nil {
		return "", err
	}
	return string(out), nil
}
