import json
from mcp.server.fastmcp import FastMCP
from pydantic import BaseModel, Field

mcp = FastMCP("cookie-security-grader")
MAX_OUT_BYTES = 16_384

class CookieAuditInput(BaseModel):
    set_cookie_headers: list[str] = Field(..., min_length=1, max_length=50)

def _audit_single_cookie(raw_header: str) -> dict[str, object]:
    if len(raw_header) > 4096:
        raise ValueError("Set-Cookie header exceeds 4096-byte RFC limit")
    segments = [seg.strip() for seg in raw_header.split(";") if seg.strip()]
    if not segments or "=" not in segments[0]:
        return {"name": "<malformed>", "value": "[REDACTED]", "issues": ["MALFORMED_COOKIE_PAIR"]}

    cookie_name, _ = segments[0].split("=", 1)
    cookie_name = cookie_name.strip()[:128]
    attrs: dict[str, str] = {}
    for attr in segments[1:]:
        if "=" in attr:
            k, v = attr.split("=", 1)
            attrs[k.strip().lower()] = v.strip()
        else:
            attrs[attr.lower()] = "true"

    issues: list[str] = []
    is_secure = "secure" in attrs
    is_httponly = "httponly" in attrs
    samesite = attrs.get("samesite", "").lower()

    if not is_secure:
        issues.append("MISSING_SECURE_FLAG")
    if not is_httponly:
        issues.append("MISSING_HTTPONLY_FLAG")
    if samesite not in ("strict", "lax", "none"):
        issues.append("MISSING_OR_INVALID_SAMESITE")
    elif samesite == "none" and not is_secure:
        issues.append("SAMESITE_NONE_WITHOUT_SECURE")

    if cookie_name.startswith("__Host-"):
        if not is_secure or "domain" in attrs or attrs.get("path") != "/":
            issues.append("BROKEN_HOST_PREFIX_INVARIANTS")
    elif cookie_name.startswith("__Secure-") and not is_secure:
        issues.append("BROKEN_SECURE_PREFIX_INVARIANT")

    return {
        "name": cookie_name,
        "value": "[REDACTED_COOKIE_VALUE]",
        "samesite": samesite or None,
        "issues": issues,
    }

@mcp.tool()
def grade_set_cookie_headers(inp: CookieAuditInput) -> str:
    results = [_audit_single_cookie(h) for h in inp.set_cookie_headers]
    out = json.dumps({"cookies_audited": len(results), "results": results}, indent=2)
    raw = out.encode("utf-8")
    if len(raw) > MAX_OUT_BYTES:
        return raw[:MAX_OUT_BYTES].decode("utf-8", errors="ignore") + "\n...[TRUNCATED]"
    return out
