const MAX_PCAPNG_BYTES = 16 * 1024 * 1024;
const MAX_OUT_BYTES = 16_384;
const SHB_TYPE = 0x0a0d0d0a;
const IDB_TYPE = 0x00000001;
const ISB_TYPE = 0x00000005;

const PcapngMetaSchema = {
  pcapngFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.pcapng$/),
  maxBlocks: z.number().int().min(10).max(20000).default(5000),
};

export function registerPcapngInterfaceInspector(server: McpServer, pcapDir = "/var/sandbox/pcaps"): void {
  server.tool("inspect_pcapng_interfaces", PcapngMetaSchema, async ({ pcapngFile, maxBlocks }) => {
    const canonDir = await realpath(pcapDir);
    const candidate = path.join(canonDir, pcapngFile);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_PCAPNG_BYTES) {
      throw new Error("PCAPng file is symlinked, missing, or exceeds 16 MiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("PCAPng path escaped sandbox root");
    }

    const buf = await readFile(resolved, { signal: AbortSignal.timeout(3000) });
    if (buf.length < 28 || buf.readUInt32LE(0) !== SHB_TYPE) {
      throw new Error("Not a valid PCAPng Section Header Block");
    }
    const bom = buf.readUInt32LE(8);
    const le = bom === 0x1a2b3c4d;
    if (!le && bom !== 0x4d3c2b1a) {
      throw new Error("Unrecognized PCAPng byte-order magic");
    }

    const interfaces: Array<{ index: number; linkType: number; snapLen: number }> = [];
    let isbCount = 0;
    let blocksVisited = 0;
    let offset = 0;

    while (offset + 12 <= buf.length && blocksVisited < maxBlocks) {
      const bType = le ? buf.readUInt32LE(offset) : buf.readUInt32BE(offset);
      const bLen = le ? buf.readUInt32LE(offset + 4) : buf.readUInt32BE(offset + 4);
      if (bLen < 12 || bLen % 4 !== 0 || offset + bLen > buf.length) {
        throw new Error("Corrupt PCAPng block length");
      }
      const trailer = le ? buf.readUInt32LE(offset + bLen - 4) : buf.readUInt32BE(offset + bLen - 4);
      if (trailer !== bLen) {
        throw new Error("Mismatched PCAPng trailing block total length");
      }
      if (bType === IDB_TYPE && bLen >= 20) {
        const linkType = le ? buf.readUInt16LE(offset + 8) : buf.readUInt16BE(offset + 8);
        const snapLen = le ? buf.readUInt32LE(offset + 12) : buf.readUInt32BE(offset + 12);
        interfaces.push({ index: interfaces.length, linkType, snapLen });
      } else if (bType === ISB_TYPE) {
        isbCount++;
      }
      offset += bLen;
      blocksVisited++;
