		Cpu:                 mf.Cpu.String(),
		FileType:            mf.Type.String(),
		PIE:                 (mf.Flags & mhPie) != 0,
		AllowStackExecution: (mf.Flags & mhAllowStackExecution) != 0,
		NoHeapExecution:     (mf.Flags & mhNoHeapExecution) != 0,
		ImportedDylibs:      dylibs,
		Rpaths:              rpaths,
	}
	out, err := json.MarshalIndent(rep, "", "  ")
	if err != nil {
