use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Path, PathBuf};
use subtle::ConstantTimeEq;
use tokio::time::{timeout, Duration};

const MAX_ARTIFACT_BYTES: u64 = 64 * 1024 * 1024;
const MAX_OUT_BYTES: usize = 32_768;

#[derive(Deserialize)]
pub struct SumsVerifyArgs {
    pub sums_file: String,
}

#[derive(Serialize)]
pub struct FileDigestStatus {
    pub file: String,
    pub verified: bool,
    pub error: Option<String>,
}

fn open_confined_regular(canon_root: &Path, name: &str) -> Result<std::fs::File, String> {
    if name.is_empty() || name.contains('/') || name.contains("..") || name.contains('\0') {
        return Err("Disallowed relative filename".into());
    }
    let candidate = canon_root.join(name);
    let meta = std::fs::symlink_metadata(&candidate).map_err(|_| "File not found".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_ARTIFACT_BYTES {
        return Err("Symlinked, special, or oversized file".into());
    }
    let f = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&candidate)
        .map_err(|e| e.to_string())?;
    let resolved = candidate.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if resolved.parent() != Some(canon_root) {
        return Err("Escaped sandbox root".into());
    }
    Ok(f)
}

pub async fn verify_sha256sums_manifest(sandbox: PathBuf, args: SumsVerifyArgs) -> Result<String, String> {
    let task = tokio::task::spawn_blocking(move || -> Result<String, String> {
        let canon_root = sandbox.canonicalize().map_err(|_| "Invalid sandbox directory".to_string())?;
        let mut sums_f = open_confined_regular(&canon_root, &args.sums_file)?;
        let mut manifest_text = String::new();
        sums_f.take(262_144).read_to_string(&mut manifest_text).map_err(|e| e.to_string())?;

        let mut results: Vec<FileDigestStatus> = Vec::new();
        for line in manifest_text.lines().take(200) {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            let mut parts = trimmed.split_whitespace();
            let hex_expected = parts.next().unwrap_or("");
            let raw_target = parts.next().unwrap_or("").trim_start_matches('*');
            if hex_expected.len() != 64 {
                results.push(FileDigestStatus {
                    file: raw_target.chars().take(128).collect(),
                    verified: false,
                    error: Some("Malformed SHA-256 hex digest".into()),
                });
                continue;
            }
            match open_confined_regular(&canon_root, raw_target) {
                Err(err_msg) => results.push(FileDigestStatus {
                    file: raw_target.chars().take(128).collect(),
                    verified: false,
                    error: Some(err_msg),
                }),
                Ok(mut art_f) => {
                    let mut hasher = Sha256::new();
                    let mut buf = [0u8; 32_768];
                    loop {
                        let n = art_f.read(&mut buf).map_err(|e| e.to_string())?;
                        if n == 0 {
                            break;
                        }
                        hasher.update(&buf[..n]);
                    }
                    let actual_hex = format!("{:x}", hasher.finalize());
                    let eq = bool::from(actual_hex.as_bytes().ct_eq(hex_expected.to_ascii_lowercase().as_bytes()));
                    results.push(FileDigestStatus {
                        file: raw_target.to_string(),
                        verified: eq,
                        error: None,
                    });
                }
            }
        }

        let mut out = serde_json::to_string_pretty(&results).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(5), task)
        .await
        .map_err(|_| "SHA256SUMS verification timed out".to_string())?
        .map_err(|e| e.to_string())?
}
