package npmaudit

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	maxLockBytes = 8 * 1024 * 1024
	maxOutBytes  = 32 * 1024
)

var allowedHosts = map[string]bool{
	"registry.npmjs.org": true,
}

type npmLockDoc struct {
	Packages map[string]struct {
		Resolved  string `json:"resolved"`
		Integrity string `json:"integrity"`
	} `json:"packages"`
}

func AuditNpmRegistryHosts(ctx context.Context, workspaceDir string, projectSubdir string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	cleanSub := filepath.Clean(projectSubdir)
	if strings.HasPrefix(cleanSub, "..") || filepath.IsAbs(cleanSub) {
		return "", errors.New("invalid relative project directory")
	}

	root, err := os.OpenRoot(workspaceDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	targetRel := filepath.Join(cleanSub, "package-lock.json")
	fi, err := root.Lstat(targetRel)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxLockBytes {
		return "", errors.New("package-lock.json missing, symlinked, or exceeds 8 MiB")
	}

	f, err := root.Open(targetRel)
	if err != nil {
		return "", err
	}
	defer f.Close()

	raw, err := io.ReadAll(io.LimitReader(f, maxLockBytes))
	if err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}

	var doc npmLockDoc
	if err := json.Unmarshal(raw, &doc); err != nil {
		return "", errors.New("failed to parse package-lock.json")
	}

	type hostViolation struct {
		Package string `json:"package"`
		SafeURL string `json:"resolved_url"`
		Reason  string `json:"reason"`
	}
	var violations []hostViolation

	for pkgPath, entry := range doc.Packages {
		if pkgPath == "" || entry.Resolved == "" {
			continue
		}
		u, err := url.Parse(entry.Resolved)
		if err != nil {
			violations = append(violations, hostViolation{pkgPath, "[MALFORMED_URL]", "INVALID_RESOLVED_URL"})
			continue
		}
		u.User = nil
		u.RawQuery = ""
		safeURL := u.String()
		if u.Scheme != "https" {
			violations = append(violations, hostViolation{pkgPath, safeURL, "NON_HTTPS_TARBALL_SCHEME"})
		} else if !allowedHosts[strings.ToLower(u.Hostname())] {
			violations = append(violations, hostViolation{pkgPath, safeURL, "UNAPPROVED_TARBALL_HOST"})
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"packages_checked": len(doc.Packages),
		"violation_count":  len(violations),
		"violations":       violations,
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(out), nil
}
