const MAX_SSH_BYTES = 131_072;
const MAX_OUT_BYTES = 16_384;
const KEY_TYPES = new Set([
  "ssh-ed25519",
  "sk-ssh-ed25519@openssh.com",
  "ecdsa-sha2-nistp256",
