function parseRsaModulusBits(b64Blob: string): number | null {
  const buf = Buffer.from(b64Blob, "base64");
  let off = 0;
  const readMpint = (): Buffer | null => {
    if (off + 4 > buf.length) return null;
    const len = buf.readUInt32BE(off);
    off += 4;
    if (off + len > buf.length) return null;
    const slice = buf.subarray(off, off + len);
    off += len;
    return slice;
  };
  if (!readMpint() || !readMpint()) return null; // keytype, e
  const n = readMpint();
  if (!n) return null;
  const stripped = n[0] === 0 ? n.subarray(1) : n;
  return stripped.length * 8;
}

export function registerSshKeyAuditor(server: McpServer, sshDir = "/srv/sandbox/ssh"): void {
