      throw new Error("SSH file escaped sandbox root");
    }

    const raw = await readFile(resolved, { encoding: "utf8", signal: AbortSignal.timeout(2000) });
    if (raw.includes("PRIVATE KEY")) {
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({ criticalError: "PRIVATE_KEY_DETECTED_AND_REDACTED", entries: [] }, null, 2),
          },
        ],
      };
    }

    const entries = raw
      .split(/\r?\n/)
      .map((l) => l.trim())
      .filter((l) => l && !l.startsWith("#"))
      .slice(0, 200)
      .map((line, idx) => {
        const tokens = line.split(/\s+/);
        const typeIdx = tokens.findIndex((t) => KEY_TYPES.has(t));
        if (typeIdx < 0 || !tokens[typeIdx + 1]) {
          return { line: idx + 1, keyType: "unknown", warnings: ["UNRECOGNIZED_SSH_KEY_FORMAT"] };
