        const ktype = tokens[typeIdx];
        const blob = tokens[typeIdx + 1];
        const warnings: string[] = [];
        if (ktype === "ssh-dss") warnings.push("DEPRECATED_DSA_KEY");
        if (ktype === "ssh-rsa") {
