use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct DnsRcodeArgs {
    pub pcap_name: String,
    pub max_packets: usize,
}

#[derive(Serialize)]
pub struct DnsRcodeReport {
    pub packets_scanned: usize,
    pub dns_responses: usize,
    pub truncated_tc_count: usize,
    pub rcode_histogram: BTreeMap<String, usize>,
}

fn rcode_label(code: u8) -> String {
    match code {
        0 => "NOERROR".into(),
        1 => "FORMERR".into(),
        2 => "SERVFAIL".into(),
        3 => "NXDOMAIN".into(),
        5 => "REFUSED".into(),
        other => format!("RCODE_{other}"),
    }
}

pub async fn summarize_dns_rcodes(sandbox: PathBuf, args: DnsRcodeArgs) -> Result<String, String> {
    let cap = args.max_packets.clamp(1, 10_000);
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.pcap_name.ends_with(".pcap") || args.pcap_name.contains('/') || args.pcap_name.contains("..") {
            return Err("Invalid .pcap filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.pcap_name);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "PCAP not found".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return Err("Symlinks and special files forbidden".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut ghdr = [0u8; 24];
        f.read_exact(&mut ghdr).map_err(|_| "Truncated PCAP global header".to_string())?;
        let magic = u32::from_le_bytes(ghdr[0..4].try_into().unwrap());
        let le = magic == 0xa1b2_c3d4 || magic == 0xa1b2_3c4d;
        if !le && magic != 0xd4c3_b2a1 && magic != 0x4d3c_b2a1 {
            return Err("Unsupported PCAP magic".into());
        }

        let mut rhdr = [0u8; 16];
        let mut frame = vec![0u8; 65_536];
        let mut packets_scanned: usize = 0;
        let mut dns_responses: usize = 0;
        let mut truncated_tc_count: usize = 0;
        let mut rcode_histogram: BTreeMap<String, usize> = BTreeMap::new();

        while packets_scanned < cap && f.read_exact(&mut rhdr).is_ok() {
            let incl_len = if le {
                u32::from_le_bytes(rhdr[8..12].try_into().unwrap()) as usize
            } else {
                u32::from_be_bytes(rhdr[8..12].try_into().unwrap()) as usize
            };
            if incl_len > frame.len() {
                return Err("Packet exceeds 64 KiB buffer".into());
            }
            f.read_exact(&mut frame[..incl_len]).map_err(|e| e.to_string())?;
            packets_scanned += 1;

            if incl_len >= 54 && u16::from_be_bytes([frame[12], frame[13]]) == 0x0800 && frame[23] == 17 {
                let ihl = ((frame[14] & 0x0f) as usize) * 4;
                if ihl >= 20 && incl_len >= 14 + ihl + 20 {
                    let src_port = u16::from_be_bytes([frame[14 + ihl], frame[14 + ihl + 1]]);
                    let dns_off = 14 + ihl + 8;
                    let flags_hi = frame[dns_off + 2];
                    let flags_lo = frame[dns_off + 3];
                    if src_port == 53 && (flags_hi & 0x80) != 0 {
                        dns_responses += 1;
                        if (flags_hi & 0x02) != 0 {
                            truncated_tc_count += 1;
                        }
                        *rcode_histogram.entry(rcode_label(flags_lo & 0x0f)).or_insert(0) += 1;
                    }
                }
            }
        }

        let rep = DnsRcodeReport {
            packets_scanned,
            dns_responses,
            truncated_tc_count,
            rcode_histogram,
        };
        let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "PCAP DNS RCODE scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
