use regex::Regex;
use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;

const MAX_ACTION_BYTES: u64 = 131_072;
const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct ActionYmlArgs {
    pub action_subdir: String,
}

#[derive(Serialize)]
pub struct ActionFinding {
    pub line: usize,
    pub code: String,
    pub snippet: String,
}

pub fn lint_composite_action_yml(repo_root: &Path, args: ActionYmlArgs) -> Result<String, String> {
    if args.action_subdir.contains("..") || args.action_subdir.starts_with('/') || args.action_subdir.contains('\0') {
        return Err("Invalid relative action subdirectory".into());
    }
    let canon_root = repo_root.canonicalize().map_err(|_| "Repo root missing".to_string())?;
    let target = canon_root.join(&args.action_subdir).join("action.yml");
    let meta = std::fs::symlink_metadata(&target).map_err(|_| "action.yml not found".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_ACTION_BYTES {
        return Err("Symlinked, non-regular, or oversized action.yml".into());
    }
    let mut f = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&target)
        .map_err(|e| e.to_string())?;
    let resolved = target.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if !resolved.starts_with(&canon_root) {
        return Err("action.yml escaped repository root".into());
    }

    let mut raw = String::new();
    f.read_to_string(&mut raw).map_err(|e| e.to_string())?;

    let tok_re = Regex::new(r"(gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})").unwrap();
    let docker_re = Regex::new(r"^\s*image:\s*['\"]?docker://([^'\"\s]+)").unwrap();
    let input_expr_re = Regex::new(r"\$\{\{\s*inputs\.[a-zA-Z0-9_-]+\s*\}\}").unwrap();

    let mut findings: Vec<ActionFinding> = Vec::new();
    let mut in_run_block = false;

    for (idx, raw_line) in raw.lines().enumerate() {
        let clean = tok_re.replace_all(raw_line, "[REDACTED]").into_owned();
        if let Some(caps) = docker_re.captures(&clean) {
            let img = caps.get(1).map(|m| m.as_str()).unwrap_or("");
            if !img.contains("@sha256:") {
                findings.push(ActionFinding {
                    line: idx + 1,
                    code: "UNPINNED_DOCKER_ACTION_IMAGE".into(),
                    snippet: clean.trim().chars().take(120).collect(),
                });
            }
        }
        let trimmed = clean.trim_start();
        if trimmed.starts_with("run:") || trimmed.starts_with("- run:") {
            in_run_block = true;
        } else if trimmed.starts_with("- name:") || trimmed.starts_with("shell:") || trimmed.starts_with("env:") {
            if !trimmed.starts_with("run:") {
                in_run_block = false;
            }
        }
        if (in_run_block || trimmed.contains("run:")) && input_expr_re.is_match(&clean) {
            findings.push(ActionFinding {
                line: idx + 1,
                code: "UNSAFE_INPUT_INTERPOLATION_IN_RUN".into(),
                snippet: clean.trim().chars().take(120).collect(),
            });
        }
    }

    let mut out = serde_json::to_string_pretty(&findings).map_err(|e| e.to_string())?;
    if out.len() > MAX_OUT_BYTES {
        out.truncate(MAX_OUT_BYTES);
    }
    Ok(out)
}
