package elfhardening

import (
	"context"
	"debug/elf"
	"encoding/json"
	"errors"
	"os"
	"strings"
	"time"
)

const (
	maxOutBytes = 16 * 1024
	ptGnuRelro  = elf.ProgType(0x6474e552)
)

type ElfRelroReport struct {
	RelroMode   string   `json:"relro_mode"`
	Rpaths      []string `json:"rpaths"`
	Runpaths    []string `json:"runpaths"`
	RiskyPaths  []string `json:"risky_search_paths"`
}

func checkRiskyPaths(entries []string) []string {
	var risky []string
	for _, list := range entries {
		for _, p := range strings.Split(list, ":") {
			if p == "" || p == "." || strings.Contains(p, "$ORIGIN") || !strings.HasPrefix(p, "/") || strings.HasPrefix(p, "/tmp") {
				risky = append(risky, p)
			}
		}
	}
	return risky
}

func AuditElfRelroAndRpath(ctx context.Context, sandboxDir string, binName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if binName == "" || strings.ContainsAny(binName, "/\\") || strings.Contains(binName, "..") {
		return "", errors.New("invalid ELF binary name")
	}

	root, err := os.OpenRoot(sandboxDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(binName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("ELF file missing, symlinked, or non-regular")
	}

	f, err := root.Open(binName)
	if err != nil {
		return "", err
	}
	defer f.Close()

	if err := ctx.Err(); err != nil {
		return "", err
	}
	ef, err := elf.NewFile(f)
	if err != nil {
		return "", errors.New("failed to parse ELF header")
	}
	defer ef.Close()

	hasGnuRelro := false
	for _, p := range ef.Progs {
		if p.Type == ptGnuRelro {
			hasGnuRelro = true
			break
		}
	}

	rpaths, _ := ef.DynString(elf.DT_RPATH)
	runpaths, _ := ef.DynString(elf.DT_RUNPATH)
	flags, _ := ef.DynValue(elf.DT_FLAGS)
	flags1, _ := ef.DynValue(elf.DT_FLAGS_1)
	bindNowVals, _ := ef.DynValue(elf.DT_BIND_NOW)

	hasBindNow := len(bindNowVals) > 0
	for _, v := range flags {
		if (v & uint64(elf.DF_BIND_NOW)) != 0 {
			hasBindNow = true
		}
	}
	for _, v := range flags1 {
		if (v & uint64(elf.DF_1_NOW)) != 0 {
			hasBindNow = true
		}
	}

	mode := "none"
	if hasGnuRelro && hasBindNow {
		mode = "full"
	} else if hasGnuRelro {
		mode = "partial"
	}

	rep := ElfRelroReport{
		RelroMode:  mode,
		Rpaths:     rpaths,
		Runpaths:   runpaths,
		RiskyPaths: checkRiskyPaths(append(append([]string{}, rpaths...), runpaths...)),
	}
	out, err := json.MarshalIndent(rep, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
