        let has_priv = String::from_utf8_lossy(&raw).contains("PRIVATE KEY");

        let der_bytes: Vec<u8> = if raw.starts_with(b"-----") {
            let (_, pem_obj) = parse_x509_pem(&raw).map_err(|_| "Invalid PEM certificate block".to_string())?;
            pem_obj.contents
        } else {
            raw
        };

        let (_, cert) = X509Certificate::from_der(&der_bytes).map_err(|_| "Invalid X.509 DER structure".to_string())?;
        let (is_ca, path_len) = match cert.basic_constraints().map_err(|_| "Duplicate BasicConstraints".to_string())? {
            Some(ext) => (ext.value.ca, ext.value.path_len_constraint),
            None => (false, None),
        };
        let (srv, cli, cs) = match cert.extended_key_usage().map_err(|_| "Duplicate EKU".to_string())? {
            Some(ext) => (ext.value.server_auth, ext.value.client_auth, ext.value.code_signing),
            None => (false, false, false),
        };

        let rep = CertProfileReport {
            subject: cert.subject().to_string(),
            is_ca,
            path_len_constraint: path_len,
            server_auth: srv,
            client_auth: cli,
            code_signing: cs,
            private_key_detected_and_redacted: has_priv,
        };
        let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(2), job)
        .await
