package cspgrade

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
)

const (
	maxCspLen   = 8192
	maxOutBytes = 16384
)

type CspAuditResult struct {
	DirectivesPresent []string `json:"directives_present"`
	NonceBitLengths   []int    `json:"nonce_bit_lengths"`
	StrictDynamic     bool     `json:"strict_dynamic"`
	Findings          []string `json:"findings"`
	ReportEndpoint    string   `json:"report_endpoint,omitempty"`
}

func AuditCspPolicy(rawPolicy string) (string, error) {
	if len(rawPolicy) == 0 || len(rawPolicy) > maxCspLen {
		return "", errors.New("CSP header must be between 1 and 8192 bytes")
	}

	dirs := make(map[string][]string)
	var names []string
	for _, part := range strings.Split(rawPolicy, ";") {
		fields := strings.Fields(strings.TrimSpace(part))
		if len(fields) == 0 {
			continue
		}
		dname := strings.ToLower(fields[0])
		if _, exists := dirs[dname]; !exists {
			names = append(names, dname)
		}
		dirs[dname] = fields[1:]
	}

	res := CspAuditResult{DirectivesPresent: names}
	scriptSrc, ok := dirs["script-src"]
	if !ok {
		scriptSrc = dirs["default-src"]
	}
	if len(scriptSrc) == 0 {
		res.Findings = append(res.Findings, "MISSING_SCRIPT_SRC_AND_DEFAULT_SRC")
	}

	for _, src := range scriptSrc {
		lc := strings.ToLower(strings.Trim(src, "'"))
		switch {
		case lc == "strict-dynamic":
			res.StrictDynamic = true
		case lc == "unsafe-inline":
			res.Findings = append(res.Findings, "SCRIPT_UNSAFE_INLINE")
		case lc == "unsafe-eval":
			res.Findings = append(res.Findings, "SCRIPT_UNSAFE_EVAL")
		case lc == "data:" || lc == "blob:":
			res.Findings = append(res.Findings, "SCRIPT_DANGEROUS_SCHEME_"+strings.ToUpper(strings.TrimSuffix(lc, ":")))
		case strings.HasPrefix(src, "'nonce-") && strings.HasSuffix(src, "'"):
			b64 := strings.TrimSuffix(strings.TrimPrefix(src, "'nonce-"), "'")
			decoded, err := base64.StdEncoding.DecodeString(b64)
			if err != nil {
				decoded, err = base64.RawStdEncoding.DecodeString(b64)
			}
			bits := len(decoded) * 8
			res.NonceBitLengths = append(res.NonceBitLengths, bits)
			if err != nil || bits < 128 {
				res.Findings = append(res.Findings, "WEAK_OR_NON_BASE64_NONCE_LT_128_BITS")
			}
		}
	}

	if obj := dirs["object-src"]; len(obj) != 1 || strings.ToLower(obj[0]) != "'none'" {
		res.Findings = append(res.Findings, "MISSING_OBJECT_SRC_NONE")
	}
	if base := dirs["base-uri"]; len(base) == 0 || (strings.ToLower(base[0]) != "'none'" && strings.ToLower(base[0]) != "'self'") {
		res.Findings = append(res.Findings, "MISSING_RESTRICTED_BASE_URI")
	}
	if rep := dirs["report-uri"]; len(rep) > 0 {
		clean := strings.SplitN(rep[0], "?", 2)[0]
		if strings.Contains(rep[0], "?") {
			clean += "?[REDACTED]"
		}
		res.ReportEndpoint = clean
	}

	out, err := json.MarshalIndent(res, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
