use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_PE_BYTES: u64 = 16 * 1024 * 1024;
const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct PeEntropyArgs {
    pub binary_name: String,
}

#[derive(Serialize)]
pub struct SectionEntropy {
    pub name: String,
    pub raw_size: u32,
    pub entropy: f64,
    pub high_entropy_packed_suspect: bool,
}

#[derive(Serialize)]
pub struct PeStaticAuthReport {
    pub has_authenticode_table: bool,
    pub sections: Vec<SectionEntropy>,
}

fn shannon_entropy(slice: &[u8]) -> f64 {
    if slice.is_empty() {
        return 0.0;
    }
    let mut counts: [usize; 256] = [0; 256];
    for &b in slice {
        counts[b as usize] += 1;
    }
    let len = slice.len() as f64;
    counts
        .iter()
        .filter(|&&c| c > 0)
        .map(|&c| {
            let p = (c as f64) / len;
            -p * p.log2()
        })
        .sum()
}

pub async fn scan_pe_entropy_and_sig_dir(sandbox: PathBuf, args: PeEntropyArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.binary_name.is_empty() || args.binary_name.contains('/') || args.binary_name.contains("..") {
            return Err("Invalid PE filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.binary_name);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Binary missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_PE_BYTES {
            return Err("Symlinked, special, or oversized PE file".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut data: Vec<u8> = Vec::new();
        f.read_to_end(&mut data).map_err(|e| e.to_string())?;

        if data.len() < 0x40 || &data[0..2] != b"MZ" {
            return Err("Missing MZ DOS header".into());
        }
        let pe_off = u32::from_le_bytes(data[0x3c..0x40].try_into().unwrap()) as usize;
        if pe_off + 24 > data.len() || &data[pe_off..pe_off + 4] != b"PE\0\0" {
            return Err("Invalid PE signature".into());
        }
        let num_sections = u16::from_le_bytes([data[pe_off + 6], data[pe_off + 7]]) as usize;
        let opt_size = u16::from_le_bytes([data[pe_off + 20], data[pe_off + 21]]) as usize;
        let opt_off = pe_off + 24;
        if opt_off + opt_size > data.len() || num_sections > 96 {
            return Err("Malformed OptionalHeader or section count".into());
        }

        let magic = u16::from_le_bytes([data[opt_off], data[opt_off + 1]]);
        let sec_dir_off = match magic {
            0x10b => opt_off + 96 + 4 * 8,
            0x20b => opt_off + 112 + 4 * 8,
            _ => return Err("Unknown PE OptionalHeader magic".into()),
        };
        let has_authenticode = if sec_dir_off + 8 <= opt_off + opt_size {
            let cert_rva = u32::from_le_bytes(data[sec_dir_off..sec_dir_off + 4].try_into().unwrap());
            let cert_sz = u32::from_le_bytes(data[sec_dir_off + 4..sec_dir_off + 8].try_into().unwrap());
            cert_rva > 0 && cert_sz > 0
        } else {
            false
        };

        let sec_table = opt_off + opt_size;
        let mut sections: Vec<SectionEntropy> = Vec::new();
        for i in 0..num_sections {
            let sh = sec_table + i * 40;
            if sh + 40 > data.len() {
                break;
            }
            let name_bytes = data[sh..sh + 8].split(|&b| b == 0).next().unwrap_or(&[]);
            let raw_size = u32::from_le_bytes(data[sh + 16..sh + 20].try_into().unwrap());
            let raw_ptr = u32::from_le_bytes(data[sh + 20..sh + 24].try_into().unwrap()) as usize;
            let end = raw_ptr.saturating_add(raw_size as usize).min(data.len());
            let ent = if raw_ptr < end { shannon_entropy(&data[raw_ptr..end]) } else { 0.0 };
            sections.push(SectionEntropy {
                name: String::from_utf8_lossy(name_bytes).into_owned(),
                raw_size,
                entropy: (ent * 1000.0).round() / 1000.0,
                high_entropy_packed_suspect: ent > 7.2,
            });
        }

        let rep = PeStaticAuthReport {
            has_authenticode_table: has_authenticode,
            sections,
        };
        let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "PE entropy scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
