```rust
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct VlanScanArgs {
    pub pcap_file: String,
    pub max_packets: usize,
}

#[derive(Serialize)]
pub struct VlanReport {
    pub packets_scanned: usize,
    pub single_tagged_vlans: BTreeMap<u16, usize>,
    pub double_tagged_frames: usize,
}

pub async fn detect_pcap_vlan_stacking(sandbox: PathBuf, args: VlanScanArgs) -> Result<String, String> {
    let pkt_cap = args.max_packets.clamp(1, 10_000);
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.pcap_file.ends_with(".pcap") || args.pcap_file.contains('/') || args.pcap_file.contains("..") {
            return Err("Invalid .pcap filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.pcap_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "PCAP missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return Err("Symlinks and special files forbidden".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut ghdr = [0u8; 24];
        f.read_exact(&mut ghdr).map_err(|_| "Truncated PCAP header".to_string())?;
        let magic = u32::from_le_bytes(ghdr[0..4].try_into().unwrap());
        let le = magic == 0xa1b2_c3d4 || magic == 0xa1b2_3c4d;
        if !le && magic != 0xd4c3_b2a1 && magic != 0x4d3c_b2a1 {
            return Err("Unsupported PCAP magic".into());
        }

        let mut rhdr = [0u8; 16];
        let mut buf = vec![0u8; 65_536];
        let mut packets_scanned: usize = 0;
        let mut double_tagged_frames: usize = 0;
        let mut single_tagged_vlans: BTreeMap<u16, usize> = BTreeMap::new();

        while packets_scanned < pkt_cap && f.read_exact(&mut rhdr).is_ok() {
            let incl_len = if le {
                u32::from_le_bytes(rhdr[8..12].try_into().unwrap()) as usize
            } else {
                u32::from_be_bytes(rhdr[8..12].try_into().unwrap()) as usize
            };
            if incl_len > buf.len() {
                return Err("Frame exceeds 64 KiB cap".into());
            }
            f.read_exact(&mut buf[..incl_len]).map_err(|e| e.to_string())?;
            packets_scanned += 1;

            if incl_len >= 22 {
                let outer_et = u16::from_be_bytes([buf[12], buf[13]]);
                if outer_et == 0x8100 || outer_et == 0x88a8 {
                    let outer_vid = u16::from_be_bytes([buf[14], buf[15]]) & 0x0fff;
                    let inner_et = u16::from_be_bytes([buf[16], buf[17]]);
                    if inner_et == 0x8100 || inner_et == 0x88a8 {
                        double_tagged_frames += 1;
                    } else {
                        *single_tagged_vlans.entry(outer_vid).or_insert(0) += 1;
                    }
                }
            }
        }

        let rep = VlanReport {
            packets_scanned,
            single_tagged_vlans,
            double_tagged_frames,
        };
        let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "VLAN scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
