package ghaaudit

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	maxYamlBytes = 256 * 1024
	maxOutBytes  = 24 * 1024
)

var (
	shaPinRe = regexp.MustCompile(`@[0-9a-f]{40}\b`)
	ghTokRe  = regexp.MustCompile(`(gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})`)
)

type ArtifactStepIssue struct {
	Line   int    `json:"line"`
	Action string `json:"action"`
	Reason string `json:"reason"`
}

func AuditWorkflowArtifactSteps(ctx context.Context, repoDir string, wfName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if (!strings.HasSuffix(wfName, ".yml") && !strings.HasSuffix(wfName, ".yaml")) ||
		strings.ContainsAny(wfName, "/\\") || strings.Contains(wfName, "..") {
		return "", errors.New("invalid workflow filename")
	}

	root, err := os.OpenRoot(repoDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	relPath := filepath.Join(".github", "workflows", wfName)
	fi, err := root.Lstat(relPath)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxYamlBytes {
		return "", errors.New("workflow missing, symlinked, or exceeds 256 KiB")
	}

	f, err := root.Open(relPath)
	if err != nil {
		return "", err
	}
	defer f.Close()

	raw, err := io.ReadAll(io.LimitReader(f, maxYamlBytes))
	if err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}

	clean := ghTokRe.ReplaceAllString(string(raw), "[REDACTED]")
	lines := strings.Split(clean, "\n")
	var issues []ArtifactStepIssue

	for i, line := range lines {
		t := strings.TrimSpace(line)
		if !strings.Contains(t, "uses:") {
			continue
		}
		if strings.Contains(t, "actions/download-artifact") || strings.Contains(t, "actions/upload-artifact") || strings.Contains(t, "actions/cache") {
			if !shaPinRe.MatchString(t) {
				issues = append(issues, ArtifactStepIssue{i + 1, t, "UNPINNED_ARTIFACT_OR_CACHE_ACTION"})
			}
		}
		if strings.Contains(t, "actions/download-artifact") {
			hasPath := false
			for j := i + 1; j < len(lines) && j <= i+8; j++ {
				next := strings.TrimSpace(lines[j])
				if strings.HasPrefix(next, "- ") {
					break
				}
				if strings.HasPrefix(next, "path:") {
					hasPath = true
					break
				}
			}
			if !hasPath {
				issues = append(issues, ArtifactStepIssue{i + 1, t, "DOWNLOAD_ARTIFACT_MISSING_SUBDIR_PATH"})
			}
		}
	}

	out, err := json.MarshalIndent(map[string]any{"workflow": wfName, "issues": issues}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
