import json
import os
import re
import time
from pathlib import Path
from mcp.server.fastmcp import FastMCP
from pydantic import BaseModel, Field

mcp = FastMCP("spdx-tagvalue-auditor")
SBOM_ROOT = Path("/srv/sandbox/sboms").resolve()
MAX_SPDX_BYTES = 4_194_304
MAX_OUT_BYTES = 32_768
SHA256_TV_RE = re.compile(r"^SHA256:\s*[0-9a-fA-F]{64}$")
URL_CRED_RE = re.compile(r"(?i)(https?://)([^/@\s]+@)")

class SpdxTvInput(BaseModel):
    spdx_file: str = Field(..., pattern=r"^[a-zA-Z0-9_.-]+\.spdx$")

def _read_confined_spdx(name: str) -> str:
    target = SBOM_ROOT / name
    if target.is_symlink():
        raise ValueError("Symlink SPDX files are forbidden")
    resolved = target.resolve(strict=True)
    if resolved.parent != SBOM_ROOT or not resolved.is_file():
        raise ValueError("SPDX file escapes sandbox")
    fd = os.open(str(resolved), os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        st = os.fstat(fd)
        if st.st_size > MAX_SPDX_BYTES:
            raise ValueError("SPDX file exceeds 4 MiB cap")
        return os.read(fd, MAX_SPDX_BYTES).decode("utf-8", errors="replace")
    finally:
        os.close(fd)

@mcp.tool()
def audit_spdx_tag_value(inp: SpdxTvInput) -> str:
    deadline = time.monotonic() + 2.5
    content = _read_confined_spdx(inp.spdx_file)
    findings: list[dict[str, object]] = []
    cur: dict[str, object] | None = None

    def _flush(pkg: dict[str, object] | None) -> None:
        if not pkg:
            return
        issues: list[str] = []
        if not pkg.get("has_sha256"):
            issues.append("MISSING_SHA256_CHECKSUM")
        lic = str(pkg.get("license", ""))
        if not lic or lic in ("NOASSERTION", "NONE"):
            issues.append("UNASSERTED_DECLARED_LICENSE")
        if issues:
            findings.append({"package": pkg["name"], "download": pkg.get("download"), "issues": issues})

    for raw_line in content.splitlines():
        if time.monotonic() > deadline:
            raise TimeoutError("SPDX Tag-Value scan timed out")
        line = raw_line.strip()
        if not line or line.startswith("#") or ":" not in line:
            continue
        tag, val = line.split(":", 1)
        tag, val = tag.strip(), val.strip()
        if tag == "PackageName":
            _flush(cur)
            cur = {"name": val[:128], "has_sha256": False, "license": "", "download": ""}
        elif cur is not None:
            if tag == "PackageChecksum" and SHA256_TV_RE.match(val):
                cur["has_sha256"] = True
            elif tag == "PackageLicenseDeclared":
                cur["license"] = val[:128]
            elif tag == "PackageDownloadLocation":
                cur["download"] = URL_CRED_RE.sub(r"\1[REDACTED]@", val)[:200]
    _flush(cur)

    out = json.dumps({"file": inp.spdx_file, "findings_count": len(findings), "findings": findings[:200]}, indent=2)
    raw = out.encode("utf-8")
    if len(raw) > MAX_OUT_BYTES:
        return raw[:MAX_OUT_BYTES].decode("utf-8", errors="ignore") + "\n...[TRUNCATED]"
    return out
