const (
	maxGoSrcBytes = 512 * 1024
	maxOutBytes   = 16 * 1024
)

type GoAstFinding struct {
	Line int    `json:"line"`
	Kind string `json:"kind"`
}

func ScanGoSourceStatic(ctx context.Context, srcDir string, fileName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if !strings.HasSuffix(fileName, ".go") || strings.ContainsAny(fileName, "/\\") || strings.Contains(fileName, "..") {
		return "", errors.New("invalid .go filename")
	}

	root, err := os.OpenRoot(srcDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(fileName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxGoSrcBytes {
		return "", errors.New("Go file missing, symlinked, or exceeds 512 KiB")
	}

