	if err != nil {
		return "", err
	}
	defer f.Close()

	raw, err := io.ReadAll(io.LimitReader(f, maxGoSrcBytes))
	if err != nil {
		return "", err
	}

	fset := token.NewFileSet()
	fileAst, err := parser.ParseFile(fset, fileName, raw, 0)
	if err != nil {
		return "", errors.New("Go syntax error during static AST parse")
	}

	var findings []GoAstFinding
	for _, imp := range fileAst.Imports {
		p := strings.Trim(imp.Path.Value, `"`)
		switch p {
		case "unsafe":
			findings = append(findings, GoAstFinding{fset.Position(imp.Pos()).Line, "IMPORT_UNSAFE_PACKAGE"})
		case "crypto/md5", "crypto/sha1":
			findings = append(findings, GoAstFinding{fset.Position(imp.Pos()).Line, "IMPORT_WEAK_HASH_PACKAGE"})
		case "net/http/cgi":
			findings = append(findings, GoAstFinding{fset.Position(imp.Pos()).Line, "IMPORT_LEGACY_CGI"})
		}
	}

	ast.Inspect(fileAst, func(n ast.Node) bool {
		if ctx.Err() != nil || n == nil {
			return false
