use hmac::{Hmac, Mac};
use serde::{Deserialize, Serialize};
use sha2::Sha256;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::time::{timeout, Duration};

const MAX_BODY_BYTES: u64 = 1_048_576;
type HmacSha256 = Hmac<Sha256>;

#[derive(Deserialize)]
pub struct WebhookVerifyArgs {
    pub body_file: String,
    pub signature_header: String,
    pub delivery_epoch: u64,
    pub secret_slot: String,
}

#[derive(Serialize)]
pub struct WebhookVerifyReport {
    pub signature_valid: bool,
    pub within_replay_window: bool,
    pub secret_slot: String,
    pub signature_preview: &'static str,
}

pub async fn verify_webhook_hmac(sandbox: PathBuf, args: WebhookVerifyArgs) -> Result<String, String> {
    if args.secret_slot != "GITHUB_WEBHOOK_SECRET" && args.secret_slot != "STRIPE_WEBHOOK_SECRET" {
        return Err("Disallowed webhook secret_slot".into());
    }
    let hex_sig = args
        .signature_header
        .strip_prefix("sha256=")
        .ok_or("signature_header must start with sha256=")?;
    let sig_bytes = hex::decode(hex_sig).map_err(|_| "Malformed hex signature (redacted)".to_string())?;
    if sig_bytes.len() != 32 {
        return Err("Expected 32-byte SHA-256 MAC".into());
    }

    let secret = std::env::var(&args.secret_slot).map_err(|_| "Secret slot not configured on server".to_string())?;
    if secret.len() < 24 {
        return Err("Configured webhook secret is too short".into());
    }

    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.body_file.is_empty() || args.body_file.contains('/') || args.body_file.contains("..") {
            return Err("Invalid body filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.body_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Payload file missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_BODY_BYTES {
            return Err("Symlinked, special, or oversized webhook body".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut body: Vec<u8> = Vec::new();
        f.read_to_end(&mut body).map_err(|e| e.to_string())?;

        let mut mac = HmacSha256::new_from_slice(secret.as_bytes()).map_err(|_| "HMAC init error".to_string())?;
        mac.update(&body);
        let sig_ok = mac.verify_slice(&sig_bytes).is_ok();

        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
        let fresh = now.abs_diff(args.delivery_epoch) <= 300;

        let rep = WebhookVerifyReport {
            signature_valid: sig_ok,
            within_replay_window: fresh,
            secret_slot: args.secret_slot,
            signature_preview: "[REDACTED]",
        };
        serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "Webhook verification timed out".to_string())?
        .map_err(|e| e.to_string())?
}
