package x509ku

import (
	"context"
	"crypto/x509"
	"encoding/json"
	"encoding/pem"
	"errors"
	"io"
	"net"
	"os"
	"strings"
	"time"
)

const (
	maxPemBytes = 256 * 1024
	maxOutBytes = 16 * 1024
)

type KeyUsageArgs struct {
	PemFile    string `json:"pem_file"`
	ExpectedIP string `json:"expected_ip"`
}

func AuditCertKeyUsageAndIpSan(ctx context.Context, certDir string, args KeyUsageArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if !strings.HasSuffix(args.PemFile, ".pem") || strings.ContainsAny(args.PemFile, "/\\") || strings.Contains(args.PemFile, "..") {
		return "", errors.New("invalid PEM filename")
	}

	root, err := os.OpenRoot(certDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.PemFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("certificate file missing, symlinked, or non-regular")
	}
	f, err := root.Open(args.PemFile)
	if err != nil {
		return "", err
	}
	defer f.Close()

	raw, err := io.ReadAll(io.LimitReader(f, maxPemBytes))
	if err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}

	var cert *x509.Certificate
	privRedacted := false
	rest := raw
	for len(rest) > 0 {
		var blk *pem.Block
		blk, rest = pem.Decode(rest)
		if blk == nil {
			break
		}
		if strings.Contains(blk.Type, "PRIVATE KEY") {
			privRedacted = true
			continue
		}
		if blk.Type == "CERTIFICATE" && cert == nil {
			c, err := x509.ParseCertificate(blk.Bytes)
			if err != nil {
				return "", errors.New("malformed X.509 certificate")
			}
			cert = c
		}
	}
	if cert == nil {
		return "", errors.New("no CERTIFICATE block found")
	}

	var issues []string
	if !cert.IsCA && (cert.KeyUsage&x509.KeyUsageCertSign) != 0 {
		issues = append(issues, "NON_CA_LEAF_HAS_KEY_CERT_SIGN")
	}
	if !cert.IsCA && (cert.KeyUsage&x509.KeyUsageDigitalSignature) == 0 {
		issues = append(issues, "LEAF_MISSING_DIGITAL_SIGNATURE_KU")
	}

	var ipSans []string
	for _, ip := range cert.IPAddresses {
		ipSans = append(ipSans, ip.String())
	}
	if args.ExpectedIP != "" {
		want := net.ParseIP(args.ExpectedIP)
		if want == nil {
			return "", errors.New("expected_ip is not a valid IP address")
		}
		matched := false
		for _, ip := range cert.IPAddresses {
			if ip.Equal(want) {
				matched = true
				break
			}
		}
		if !matched {
			issues = append(issues, "IP_SAN_MISMATCH")
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"subject":              cert.Subject.String(),
		"is_ca":                cert.IsCA,
		"ip_sans":              ipSans,
		"private_key_redacted": privRedacted,
		"issues":               issues,
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
