import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { lstat, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_PCAP_BYTES = 8 * 1024 * 1024;
const MAX_OUT_BYTES = 16_384;

const GratuitousArpSchema = {
  pcapFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.pcap$/),
  maxPackets: z.number().int().min(1).max(5000).default(2000),
};

function fmtMac(b: Buffer): string {
  return [...b].map((x) => x.toString(16).padStart(2, "0")).join(":");
}

function fmtIpv4(b: Buffer): string {
  return `${b[0]}.${b[1]}.${b[2]}.${b[3]}`;
}

export function registerGratuitousArpScanner(server: McpServer, pcapDir = "/var/sandbox/pcaps"): void {
  server.tool("detect_gratuitous_arp_pure", GratuitousArpSchema, async ({ pcapFile, maxPackets }) => {
    const canonDir = await realpath(pcapDir);
    const candidate = path.join(canonDir, pcapFile);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_PCAP_BYTES) {
      throw new Error("PCAP file is symlinked, missing, or exceeds 8 MiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("PCAP path escaped sandbox confinement");
    }

    const buf = await readFile(resolved, { signal: AbortSignal.timeout(2500) });
    if (buf.length < 24) throw new Error("Truncated PCAP global header");
    const magic = buf.readUInt32LE(0);
    const le = magic === 0xa1b2c3d4 || magic === 0xa1b23c4d;
    if (!le && magic !== 0xd4c3b2a1 && magic !== 0x4d3cb2a1) {
      throw new Error("Unsupported PCAP magic");
    }

    let off = 24;
    let pkts = 0;
    const gratuitous = new Map<string, number>();

    while (off + 16 <= buf.length && pkts < maxPackets) {
      const inclLen = le ? buf.readUInt32LE(off + 8) : buf.readUInt32BE(off + 8);
      off += 16;
      if (inclLen > 65535 || off + inclLen > buf.length) break;
      const frame = buf.subarray(off, off + inclLen);
      off += inclLen;
      pkts++;

      if (frame.length >= 42 && frame.readUInt16BE(12) === 0x0806) {
        const senderMac = fmtMac(frame.subarray(22, 28));
        const senderIp = fmtIpv4(frame.subarray(28, 32));
        const targetIp = fmtIpv4(frame.subarray(38, 42));
        if (senderIp === targetIp && senderIp !== "0.0.0.0") {
          const key = `${senderIp} (${senderMac})`;
          gratuitous.set(key, (gratuitous.get(key) ?? 0) + 1);
        }
      }
    }

    const out = JSON.stringify(
      { packetsScanned: pkts, gratuitousAnnouncements: Object.fromEntries(gratuitous) },
      null,
      2,
    );
    return { content: [{ type: "text", text: out.slice(0, MAX_OUT_BYTES) }] };
  });
}
