const MAX_PAYLOAD_BYTES = 16 * 1024 * 1024;
const ALLOWED_SLOTS = new Set(["ARTIFACT_HMAC_KEY_PRIMARY", "ARTIFACT_HMAC_KEY_SECONDARY"]);

const HmacFileSchema = {
  fileName: z.string().regex(/^[a-zA-Z0-9_.-]{1,128}$/),
  alg: z.enum(["sha384", "sha512"]),
  keySlot: z.string().refine((s) => ALLOWED_SLOTS.has(s), { message: "Disallowed HMAC key slot" }),
  expectedMacHex: z.string().regex(/^[0-9a-fA-F]{96,128}$/),
};

export function registerHmacPayloadVerifier(server: McpServer, payloadDir = "/srv/sandbox/payloads"): void {
  server.tool("verify_payload_hmac_tag", HmacFileSchema, async ({ fileName, alg, keySlot, expectedMacHex }) => {
    const expectedBytes = alg === "sha384" ? 48 : 64;
    const providedBuf = Buffer.from(expectedMacHex, "hex");
    if (providedBuf.byteLength !== expectedBytes) {
      throw new Error(`Expected ${expectedBytes}-byte hex MAC for ${alg}`);
    }

    const secret = process.env[keySlot] ?? "";
    if (Buffer.byteLength(secret, "utf8") < 32) {
      throw new Error("Configured HMAC key slot is missing or shorter than 256 bits");
    }

    const canonDir = await realpath(payloadDir);
    const candidate = path.join(canonDir, fileName);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_PAYLOAD_BYTES) {
      throw new Error("Payload file is symlinked, missing, or exceeds 16 MiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("Payload file escaped sandbox confinement");
    }

    const data = await readFile(resolved, { signal: AbortSignal.timeout(3000) });
    const actualBuf = createHmac(alg, secret).update(data).digest();
    const verified = actualBuf.byteLength === providedBuf.byteLength && timingSafeEqual(actualBuf, providedBuf);

    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(
            {
              file: fileName,
              algorithm: alg,
              keySlot,
              verified,
              keyMaterial: "[REDACTED]",
              macTag: "[REDACTED]",
            },
            null,
            2,
          ),
        },
      ],
    };
  });
}
