package pcapsmb

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

const maxOutBytes = 16 * 1024

type SmbAuditArgs struct {
	PcapFile   string `json:"pcap_file"`
	MaxPackets int    `json:"max_packets"`
}

func AuditSmbSigningPosture(ctx context.Context, pcapDir string, args SmbAuditArgs) (string, error) {
	if args.PcapFile == "" || strings.ContainsAny(args.PcapFile, "/\\") || strings.Contains(args.PcapFile, "..") {
		return "", errors.New("invalid PCAP filename")
	}
	if args.MaxPackets <= 0 || args.MaxPackets > 4000 {
		args.MaxPackets = 1500
	}

	root, err := os.OpenRoot(pcapDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.PcapFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("PCAP missing, non-regular, or symlinked")
	}
	canonRoot, err := filepath.EvalSymlinks(pcapDir)
	if err != nil {
		return "", err
	}
	canonFile, err := filepath.EvalSymlinks(filepath.Join(canonRoot, args.PcapFile))
	if err != nil || filepath.Dir(canonFile) != canonRoot {
		return "", errors.New("capture escaped sandbox")
	}

	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	argv := []string{
		"-n",
		"-r", canonFile,
		"-c", strconv.Itoa(args.MaxPackets),
		"-Y", "smb2.cmd == 0",
		"-T", "fields",
		"-E", "separator=\t",
		"-e", "ip.src",
		"-e", "ip.dst",
		"-e", "smb2.dialect",
		"-e", "smb2.sec_mode.sign_required",
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/tshark", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "HOME=/nonexistent"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("tshark SMB2 negotiation scan failed or timed out")
	}

	type negotiateRec struct {
		Src          string `json:"src"`
		Dst          string `json:"dst"`
		Dialect      string `json:"dialect"`
		SignRequired string `json:"sign_required"`
	}
	var records []negotiateRec
	for _, line := range strings.Split(stdout.String(), "\n") {
		cols := strings.Split(strings.TrimSpace(line), "\t")
		if len(cols) < 4 || cols[0] == "" {
			continue
		}
		records = append(records, negotiateRec{cols[0], cols[1], cols[2], cols[3]})
		if len(records) >= 200 {
			break
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"negotiations":  records,
		"ntlmssp_blobs": "[REDACTED]",
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
