  if (offset < 0 || offset >= buf.length) return "";
  const end = buf.indexOf(0, offset);
  const stop = end < 0 ? Math.min(buf.length, offset + 256) : Math.min(end, offset + 256);
  return buf.subarray(offset, stop).toString("utf8");
}

export function registerElfDtNeededScanner(server: McpServer, binDir = "/srv/sandbox/binaries"): void {
  server.tool("scan_elf64_dt_needed", ElfNeededSchema, async ({ binaryName }) => {
    const canonDir = await realpath(binDir);
    const candidate = path.join(canonDir, binaryName);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_ELF_BYTES) {
      throw new Error("ELF binary is symlinked, missing, or exceeds 16 MiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("Binary escaped sandbox root");
    }

    const buf = await readFile(resolved, { signal: AbortSignal.timeout(2500) });
    if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46 || buf[4] !== 2 || buf[5] !== 1) {
      throw new Error("Expected little-endian 64-bit ELF binary");
    }

    const shOff = Number(buf.readBigUInt64LE(40));
    const shEntSize = buf.readUInt16LE(58);
    const shNum = buf.readUInt16LE(60);
    if (shEntSize < 64 || shNum > 512 || shOff + shEntSize * shNum > buf.length) {
      throw new Error("Invalid or truncated ELF64 section header table");
    }

    const needed: string[] = [];
    const suspicious: string[] = [];

    for (let i = 0; i < shNum; i++) {
      const sh = shOff + i * shEntSize;
      const shType = buf.readUInt32LE(sh + 4);
      if (shType !== SHT_DYNAMIC) continue;

      const shLink = buf.readUInt32LE(sh + 40);
      if (shLink >= shNum) break;
      const strSh = shOff + shLink * shEntSize;
      const strOff = Number(buf.readBigUInt64LE(strSh + 24));
      const strSz = Number(buf.readBigUInt64LE(strSh + 32));
      if (strOff + strSz > buf.length) break;
      const dynstr = buf.subarray(strOff, strOff + strSz);

      const dynOff = Number(buf.readBigUInt64LE(sh + 24));
      const dynSz = Number(buf.readBigUInt64LE(sh + 32));
      for (let pos = dynOff; pos + 16 <= Math.min(buf.length, dynOff + dynSz); pos += 16) {
        const dTag = buf.readBigInt64LE(pos);
        const dVal = Number(buf.readBigUInt64LE(pos + 8));
        if (dTag === 0n) break;
        if (dTag === DT_NEEDED) {
          const lib = readCString(dynstr, dVal);
          needed.push(lib);
          if (lib.includes("/tmp") || lib.startsWith(".") || lib.includes("..")) {
            suspicious.push(lib);
          }
        }
      }
    }

    const out = JSON.stringify({ binary: binaryName, neededLibraries: needed, suspiciousPaths: suspicious }, null, 2);
    return { content: [{ type: "text", text: out.slice(0, MAX_OUT_BYTES) }] };
  });
}
