	if err != nil {
		return "", err
	}
	defer f.Close()

	data, err := io.ReadAll(io.LimitReader(f, maxPickleBytes))
	if err != nil {
		return "", err
	}

	rep := PickleStaticSummary{ProtocolVersion: 0}
	i := 0
	if len(data) >= 2 && data[0] == 0x80 {
		rep.ProtocolVersion = int(data[1])
		i = 2
	}

	for i < len(data) {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		op := data[i]
		i++
		switch op {
		case 'c':
			nl1 := bytes.IndexByte(data[i:], '\n')
			if nl1 < 0 {
				i = len(data)
				continue
			}
			mod := string(data[i : i+nl1])
			i += nl1 + 1
			nl2 := bytes.IndexByte(data[i:], '\n')
			if nl2 < 0 {
				i = len(data)
				continue
			}
			attr := string(data[i : i+nl2])
			i += nl2 + 1
			if len(rep.GlobalTargets) < 100 {
				combined := tokenRe.ReplaceAllString(mod+"."+attr, "[REDACTED]")
				rep.GlobalTargets = append(rep.GlobalTargets, combined)
			}
		case 0x93:
			rep.StackGlobalHits++
		case 'R':
			rep.ReduceHits++
		}
	}

	out, err := json.MarshalIndent(rep, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
