use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use rsa::pkcs8::DecodePublicKey;
use rsa::pss::{Signature, VerifyingKey};
use rsa::signature::Verifier;
use rsa::traits::PublicKeyParts;
use rsa::RsaPublicKey;
use serde::{Deserialize, Serialize};
use sha2::Sha256;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::time::{timeout, Duration};

#[derive(Deserialize)]
pub struct Ps256VerifyArgs {
    pub pub_pem_file: String,
    pub compact_jws: String,
}

#[derive(Serialize)]
pub struct Ps256VerifyOutput {
    pub alg: &'static str,
    pub signature_verified: bool,
    pub expired: bool,
    pub claims_preview: &'static str,
    pub signature_preview: &'static str,
}

pub async fn verify_ps256_jws_offline(sandbox: PathBuf, args: Ps256VerifyArgs) -> Result<String, String> {
    if args.compact_jws.len() > 8192 {
        return Err("JWS exceeds 8192 bytes (redacted)".into());
    }
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.pub_pem_file.ends_with(".pub.pem") || args.pub_pem_file.contains('/') || args.pub_pem_file.contains("..") {
            return Err("Invalid public key PEM filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let key_path = canon_root.join(&args.pub_pem_file);
        let meta = std::fs::symlink_metadata(&key_path).map_err(|_| "Public key missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > 65_536 {
            return Err("Symlinked, non-regular, or oversized public key".into());
        }
        let mut kf = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&key_path)
            .map_err(|e| e.to_string())?;
        let mut pem_str = String::new();
        kf.read_to_string(&mut pem_str).map_err(|e| e.to_string())?;
        if pem_str.contains("PRIVATE KEY") {
            return Err("Refusing PEM containing private key material".into());
        }

        let pub_key = RsaPublicKey::from_public_key_pem(&pem_str).map_err(|_| "Invalid SPKI RSA public key".to_string())?;
        if pub_key.size() * 8 < 2048 {
            return Err("RSA public key modulus smaller than 2048 bits".into());
        }

        let segs: Vec<&str> = args.compact_jws.trim().split('.').collect();
        if segs.len() != 3 {
            return Err("Malformed compact JWS (redacted)".into());
        }
        let hdr_bytes = URL_SAFE_NO_PAD.decode(segs[0]).map_err(|_| "Invalid header base64url".to_string())?;
        let claims_bytes = URL_SAFE_NO_PAD.decode(segs[1]).map_err(|_| "Invalid claims base64url".to_string())?;
        let sig_bytes = URL_SAFE_NO_PAD.decode(segs[2]).map_err(|_| "Invalid signature base64url".to_string())?;

        let hdr: serde_json::Value = serde_json::from_slice(&hdr_bytes).map_err(|_| "Invalid header JSON".to_string())?;
        if hdr.get("alg").and_then(|v| v.as_str()) != Some("PS256") {
            return Err("JWS header alg must be PS256".into());
        }
        let claims: serde_json::Value = serde_json::from_slice(&claims_bytes).map_err(|_| "Invalid claims JSON".to_string())?;
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
        let expired = match claims.get("exp").and_then(|v| v.as_u64()) {
            Some(exp) => now > exp,
            None => true,
        };

        let vk = VerifyingKey::<Sha256>::new(pub_key);
        let sig = Signature::try_from(sig_bytes.as_slice()).map_err(|_| "Malformed RSA-PSS signature length".to_string())?;
        let signing_input = format!("{}.{}", segs[0], segs[1]);
        let ok = vk.verify(signing_input.as_bytes(), &sig).is_ok();

        let rep = Ps256VerifyOutput {
            alg: "PS256",
            signature_verified: ok,
            expired,
            claims_preview: "[REDACTED]",
            signature_preview: "[REDACTED]",
        };
        serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "PS256 JWS verification timed out".to_string())?
        .map_err(|e| e.to_string())?
}
