	RpzAction string `json:"rpz_action"`
	ZoneName  string `json:"zone_name"`
	Limit     int    `json:"limit"`
}

func QueryRpzHits(ctx context.Context, logDir string, args RpzQueryArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(args.DbName, ".sqlite") || strings.ContainsAny(args.DbName, "/\\") || strings.Contains(args.DbName, "..") {
		return "", errors.New("invalid SQLite database filename")
