	defer root.Close()

	fi, err := root.Lstat(args.DbName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("RPZ database missing, symlinked, or non-regular")
	}

	canonRoot, err := filepath.EvalSymlinks(logDir)
	if err != nil {
		return "", err
	}
	canonDb, err := filepath.EvalSymlinks(filepath.Join(canonRoot, args.DbName))
