	}
	defer db.Close()

	rows, err := db.QueryContext(
		ctx,
		`SELECT event_ts, client_ip, qname, rpz_action FROM rpz_blocks WHERE rpz_action = ? AND zone_name = ? ORDER BY event_ts DESC LIMIT ?`,
		args.RpzAction, args.ZoneName, args.Limit,
	)
	if err != nil {
		return "", err
	}
