    let target = canon_root.join(name);
    let meta = std::fs::symlink_metadata(&target).map_err(|_| "PCAP file missing".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() {
        return Err("Symlinked or special files forbidden".into());
    }
    let _probe = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&target)
        .map_err(|e| e.to_string())?;
    let resolved = target.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if resolved.parent() != Some(canon_root.as_path()) {
        return Err("PCAP escaped sandbox".into());
    }
    Ok(resolved)
}

pub async fn detect_ntp_mode67_amplification(sandbox: &Path, args: NtpScanArgs) -> Result<String, String> {
    let pcap = confined_capture(sandbox, &args.pcap_name)?;
    let cap = args.max_packets.clamp(1, 5000);

    let mut cmd = Command::new("/usr/bin/tshark");
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", "/nonexistent")
        .args([
            "-n",
            "-r",
            &pcap.to_string_lossy(),
            "-c",
            &cap.to_string(),
            "-Y",
            "ntp.flags.mode == 6 || ntp.flags.mode == 7",
            "-T",
            "fields",
            "-E",
            "separator=\t",
            "-e",
            "ip.src",
            "-e",
            "ip.dst",
            "-e",
            "ntp.flags.mode",
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let out = timeout(Duration::from_secs(5), cmd.output())
        .await
        .map_err(|_| "tshark NTP scan timed out".to_string())?
        .map_err(|e| format!("Spawn error: {e}"))?;
    if !out.status.success() {
        return Err(format!("tshark returned {:?}", out.status.code()));
    }

    let mut flows: BTreeMap<String, usize> = BTreeMap::new();
    let mut total: usize = 0;
    for line in String::from_utf8_lossy(&out.stdout).lines() {
        let cols: Vec<&str> = line.split('\t').collect();
        if cols.len() >= 3 && !cols[0].is_empty() {
            total += 1;
            let key = format!("{} -> {} (mode={})", cols[0], cols[1], cols[2]);
            *flows.entry(key).or_insert(0) += 1;
        }
    }

    let rep = NtpAmpReport {
        total_control_or_private_packets: total,
        flows_by_src_dst_mode: flows,
    };
    let mut json = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
    if json.len() > MAX_OUT_BYTES {
        json.truncate(MAX_OUT_BYTES);
    }
    Ok(json)
}
