	"crypto/sha512"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"os"
	"strings"
	"time"

	"golang.org/x/crypto/blake2b"
)

const maxReleaseBytes = 128 * 1024 * 1024

type DualDigestArgs struct {
	TarballName        string `json:"tarball_name"`
	ExpectedSha512Hex  string `json:"expected_sha512_hex"`
	ExpectedBlake2bHex string `json:"expected_blake2b256_hex"`
}

func VerifyDualTarballDigests(ctx context.Context, releaseDir string, args DualDigestArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	if args.TarballName == "" || strings.ContainsAny(args.TarballName, "/\\") || strings.Contains(args.TarballName, "..") {
		return "", errors.New("invalid tarball filename")
	}
	wantSha, err1 := hex.DecodeString(strings.TrimSpace(args.ExpectedSha512Hex))
	wantB2, err2 := hex.DecodeString(strings.TrimSpace(args.ExpectedBlake2bHex))
	if err1 != nil || err2 != nil || len(wantSha) != 64 || len(wantB2) != 32 {
		return "", errors.New("expected 64-byte SHA-512 hex and 32-byte BLAKE2b-256 hex")
	}

	root, err := os.OpenRoot(releaseDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.TarballName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxReleaseBytes {
		return "", errors.New("tarball missing, symlinked, or exceeds 128 MiB")
	}
	f, err := root.Open(args.TarballName)
	if err != nil {
		return "", err
	}
	defer f.Close()

	hSha := sha512.New()
	hB2, err := blake2b.New256(nil)
	if err != nil {
		return "", err
	}

	mw := io.MultiWriter(hSha, hB2)
	buf := make([]byte, 64*1024)
	var total int64

	for {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		n, rerr := f.Read(buf)
		if n > 0 {
			total += int64(n)
			if total > maxReleaseBytes {
				return "", errors.New("tarball exceeded size cap mid-read")
			}
			_, _ = mw.Write(buf[:n])
		}
		if errors.Is(rerr, io.EOF) {
			break
		}
		if rerr != nil {
			return "", rerr
		}
	}

	shaMatch := subtle.ConstantTimeCompare(hSha.Sum(nil), wantSha) == 1
	blakeMatch := subtle.ConstantTimeCompare(hB2.Sum(nil), wantB2) == 1

	out, err := json.MarshalIndent(map[string]any{
		"file":              args.TarballName,
		"bytes_verified":    total,
		"sha512_match":      shaMatch,
		"blake2b256_match":  blakeMatch,
		"both_verified":     shaMatch && blakeMatch,
	}, "", "  ")
	return string(out), err
}
