pub async fn inspect_s3_exposure_trail(sandbox: PathBuf, args: S3TrailArgs) -> Result<String, String> {
    let hit_cap = args.max_hits.clamp(1, 150);
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.trail_file.ends_with(".jsonl") || args.trail_file.contains('/') || args.trail_file.contains("..") {
            return Err("Invalid CloudTrail .jsonl filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.trail_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Trail file missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return Err("Symlinks and special files forbidden".into());
        }
        let f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let cred_re = Regex::new(r"(AKIA[0-9A-Z]{16}|ASIA[0-9A-Z]{16})").unwrap();
        let reader = BufReader::new(f.take(MAX_SCAN_BYTES));
        let mut hits: Vec<S3ExposureEvent> = Vec::new();

        for line_res in reader.lines() {
            let line = line_res.map_err(|e| e.to_string())?;
            let Ok(val) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
            if val.get("eventSource").and_then(|v| v.as_str()) != Some("s3.amazonaws.com") {
                continue;
            }
            let ev_name = val.get("eventName").and_then(|v| v.as_str()).unwrap_or("");
            if !matches!(
                ev_name,
                "PutBucketPolicy" | "PutBucketAcl" | "PutBucketPublicAccessBlock" | "DeleteBucketPublicAccessBlock"
            ) {
                continue;
            }
            let raw_arn = val.pointer("/userIdentity/arn").and_then(|v| v.as_str()).unwrap_or("");
            hits.push(S3ExposureEvent {
                event_time: val.get("eventTime").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                event_name: ev_name.to_string(),
                bucket_name: val
                    .pointer("/requestParameters/bucketName")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string(),
                source_ip: val.get("sourceIPAddress").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                arn: cred_re.replace_all(raw_arn, "[REDACTED]").into_owned(),
            });
            if hits.len() >= hit_cap {
                break;
            }
        }

        let mut out = serde_json::to_string_pretty(&hits).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
            out.push_str("\n...[TRUNCATED]");
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "S3 CloudTrail scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
