import { lstat, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_LOCK_BYTES = 4 * 1024 * 1024;
const MAX_OUT_BYTES = 32_768;
const CRATES_IO_SRC = "registry+https://github.com/rust-lang/crates.io-index";
const CRED_RE = /((?:git\+)?https?:\/\/)([^/@\s"']+@)/gi;

const CargoTsAuditSchema = {
  repoFolder: z.string().regex(/^[a-zA-Z0-9_.-]{1,64}$/),
};

export function registerCargoLockTsAuditor(server: McpServer, rootDir = "/srv/sandbox/rust-repos"): void {
  server.tool("audit_cargo_lock_sources", CargoTsAuditSchema, async ({ repoFolder }) => {
