    const target = path.join(canonRoot, repoFolder, "Cargo.lock");
    const st = await lstat(target);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_LOCK_BYTES) {
      throw new Error("Cargo.lock is symlinked, missing, or exceeds 4 MiB");
    }
    const resolved = await realpath(target);
    if (!resolved.startsWith(canonRoot + path.sep)) {
      throw new Error("Cargo.lock escaped sandbox confinement");
    }

    const raw = await readFile(resolved, { encoding: "utf8", signal: AbortSignal.timeout(2500) });
    const blocks = raw.split(/^\[\[package\]\]/m).slice(1);
    const findings: Array<{ crate: string; version: string; issue: string; source: string }> = [];

    for (const blk of blocks) {
      const getField = (k: string): string => {
        const m = blk.match(new RegExp(`^\\s*${k}\\s*=\\s*"([^"]*)"`, "m"));
        return m ? m[1] : "";
      };
      const name = getField("name");
      const version = getField("version");
      const src = getField("source");
      const checksum = getField("checksum");
      if (!name || !src) continue;

      const safeSrc = src.replace(CRED_RE, "$1[REDACTED]@");
      if (src.startsWith("git+")) {
        if (!/#[0-9a-f]{40}$/.test(src)) {
          findings.push({ crate: name, version, issue: "GIT_DEPENDENCY_MISSING_40HEX_SHA", source: safeSrc });
        }
      } else if (src !== CRATES_IO_SRC) {
        findings.push({ crate: name, version, issue: "ALTERNATE_CARGO_REGISTRY", source: safeSrc });
      } else if (!/^[0-9a-f]{64}$/.test(checksum)) {
        findings.push({ crate: name, version, issue: "MISSING_SHA256_CHECKSUM", source: safeSrc });
      }
    }

    const out = JSON.stringify({ cratesChecked: blocks.length, findingsCount: findings.length, findings }, null, 2);
    const buf = Buffer.from(out, "utf8");
    const text =
      buf.byteLength > MAX_OUT_BYTES
        ? buf.subarray(0, MAX_OUT_BYTES).toString("utf8") + "\n...[TRUNCATED]"
        : out;
    return { content: [{ type: "text", text }] };
  });
}
