	"strings"
	"time"
)

const (
	maxSampleBytes = 16 * 1024 * 1024
	maxOutBytes    = 16 * 1024
)

var ruleCatalog = map[string]string{
	"macho-suspicious": "/opt/yara/macho_suspicious.yar",
	"pe-anomalies":     "/opt/yara/pe_anomalies.yar",
}

type YaraGoArgs struct {
	ArtifactName string `json:"artifact_name"`
	RuleKey      string `json:"rule_key"`
}

func ScanArtifactWithYara(ctx context.Context, sampleDir string, args YaraGoArgs) (string, error) {
	ruleFile, ok := ruleCatalog[args.RuleKey]
	if !ok {
		return "", errors.New("disallowed YARA rule_key")
	}
	if args.ArtifactName == "" || strings.ContainsAny(args.ArtifactName, "/\\") || strings.Contains(args.ArtifactName, "..") {
		return "", errors.New("invalid artifact filename")
	}

	root, err := os.OpenRoot(sampleDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.ArtifactName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxSampleBytes {
		return "", errors.New("artifact missing, symlinked, or exceeds 16 MiB")
	}

	canonRoot, err := filepath.EvalSymlinks(sampleDir)
	if err != nil {
		return "", err
	}
	canonTarget, err := filepath.EvalSymlinks(filepath.Join(canonRoot, args.ArtifactName))
	if err != nil || filepath.Dir(canonTarget) != canonRoot {
		return "", errors.New("artifact path escaped sandbox")
	}

	ctx, cancel := context.WithTimeout(ctx, 6*time.Second)
	defer cancel()

	argv := []string{
		"--no-follow-symlinks",
		"--threads=1",
		"--timeout=4",
		ruleFile,
		canonTarget,
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/yara", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "HOME=/nonexistent"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("yara execution failed or timed out")
	}

	var rules []string
	for _, line := range strings.Split(stdout.String(), "\n") {
		fields := strings.Fields(strings.TrimSpace(line))
		if len(fields) > 0 {
			rules = append(rules, fields[0])
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"artifact":       args.ArtifactName,
		"matched_rules":  rules,
		"matched_values": "[REDACTED]",
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
