    fd = os.open(str(resolved), os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        raw = os.read(fd, MAX_JWK_BYTES).decode("utf-8")
    finally:
        os.close(fd)
    return json.loads(raw)

@mcp.tool()
def verify_rfc7638_jwk_thumbprint(inp: JwkThumbprintInput) -> str:
    deadline = time.monotonic() + 1.5
    jwk = _load_confined_jwk(inp.jwk_file)
    if SECRET_JWK_FIELDS.intersection(jwk.keys()):
        raise ValueError("Private or symmetric JWK material detected and rejected (redacted)")

    kty = jwk.get("kty")
    if kty == "RSA":
        members = {"e": jwk["e"], "kty": "RSA", "n": jwk["n"]}
    elif kty == "EC":
        members = {"crv": jwk["crv"], "kty": "EC", "x": jwk["x"], "y": jwk["y"]}
    elif kty == "OKP":
        members = {"crv": jwk["crv"], "kty": "OKP", "x": jwk["x"]}
    else:
        raise ValueError("Unsupported public JWK kty")

    if time.monotonic() > deadline:
        raise TimeoutError("Thumbprint calculation timed out")

    canonical_json = json.dumps(members, separators=(",", ":"), sort_keys=True).encode("utf-8")
    digest = hashlib.sha256(canonical_json).digest()
    actual_tp = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
    matched = hmac.compare_digest(actual_tp, inp.expected_thumbprint)

    return json.dumps(
        {
            "jwk_file": inp.jwk_file,
            "kty": kty,
            "computed_thumbprint": actual_tp,
            "matched": matched,
        },
        indent=2,
    )
