use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

const MAX_IN_BYTES: usize = 16_384;
const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct PrivacyHeaderArgs {
    pub raw_headers: String,
    pub is_authenticated_endpoint: bool,
}

#[derive(Serialize)]
pub struct PrivacyGradeOutput {
    pub findings: Vec<String>,
    pub sanitized_headers: BTreeMap<String, String>,
}

pub fn grade_privacy_and_cache_headers(args: PrivacyHeaderArgs) -> Result<String, String> {
    if args.raw_headers.is_empty() || args.raw_headers.len() > MAX_IN_BYTES {
        return Err("Header input must be between 1 and 16384 bytes".into());
    }

    let mut map: BTreeMap<String, String> = BTreeMap::new();
    for line in args.raw_headers.lines().take(100) {
        if let Some((k, v)) = line.split_once(':') {
            let key = k.trim().to_ascii_lowercase();
            let val = v.trim();
            if matches!(key.as_str(), "cookie" | "set-cookie" | "authorization" | "x-api-key") {
                map.insert(key, "[REDACTED]".into());
            } else {
                map.insert(key, val.chars().take(300).collect());
            }
        }
    }

    let mut findings: Vec<String> = Vec::new();
    match map.get("referrer-policy").map(|s| s.to_ascii_lowercase()).as_deref() {
        None => findings.push("MISSING_REFERRER_POLICY".into()),
        Some(rp) if rp.contains("unsafe-url") || rp.contains("no-referrer-when-downgrade") => {
            findings.push("LEAKY_REFERRER_POLICY".into());
        }
        _ => {}
    }

    match map.get("permissions-policy").map(|s| s.to_ascii_lowercase()) {
        None => findings.push("MISSING_PERMISSIONS_POLICY".into()),
        Some(pp) => {
            for cap in ["camera=()", "microphone=()", "usb=()"] {
                if !pp.contains(cap) {
                    findings.push(format!("PERMISSIONS_POLICY_MISSING_{}", cap.trim_end_matches("=()").to_ascii_uppercase()));
                }
            }
        }
    }

    if args.is_authenticated_endpoint {
        let cc = map.get("cache-control").map(|s| s.to_ascii_lowercase()).unwrap_or_default();
        if !cc.contains("no-store") {
            findings.push("AUTH_RESPONSE_MISSING_CACHE_CONTROL_NO_STORE".into());
        }
    }

    let rep = PrivacyGradeOutput {
        findings,
        sanitized_headers: map,
    };
    let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
    if out.len() > MAX_OUT_BYTES {
        out.truncate(MAX_OUT_BYTES);
    }
    Ok(out)
}
