	}
	if !allowedComms[args.Comm] {
		return "", errors.New("comm is not in the allowlist")
	}
	if args.MaxEntries <= 0 || args.MaxEntries > 150 {
		args.MaxEntries = 50
	}

	ctx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	argv := []string{
		"--no-pager",
		"--quiet",
		"-o", "json",
		fmt.Sprintf("_UID=%d", args.Uid),
		"_COMM=" + args.Comm,
		"-n", strconv.Itoa(args.MaxEntries),
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/journalctl", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "LC_ALL=C"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("journalctl query failed or timed out")
	}

	var entries []map[string]any
	for _, line := range strings.Split(stdout.String(), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		var raw map[string]any
		if err := json.Unmarshal([]byte(line), &raw); err != nil {
			continue
		}
		msg, _ := raw["MESSAGE"].(string)
		entries = append(entries, map[string]any{
			"ts":      raw["__REALTIME_TIMESTAMP"],
			"pid":     raw["_PID"],
			"comm":    args.Comm,
			"message": msgSecretRe.ReplaceAllString(msg, "[REDACTED]"),
		})
	}

	out, err := json.MarshalIndent(map[string]any{"count": len(entries), "entries": entries}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(out), nil
}
