use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Read;
use std::net::Ipv4Addr;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct IcmpProfileArgs {
    pub pcap_file: String,
    pub max_packets: usize,
}

#[derive(Serialize, Default)]
pub struct EchoPairStats {
    pub echo_packets: usize,
    pub max_payload_bytes: usize,
}

pub async fn profile_icmp_echo_sizes(sandbox: PathBuf, args: IcmpProfileArgs) -> Result<String, String> {
    let pkt_cap = args.max_packets.clamp(1, 10_000);
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.pcap_file.ends_with(".pcap") || args.pcap_file.contains('/') || args.pcap_file.contains("..") {
            return Err("Invalid .pcap filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.pcap_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "PCAP not found".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return Err("Symlinks and special files forbidden".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut ghdr = [0u8; 24];
        f.read_exact(&mut ghdr).map_err(|_| "Truncated PCAP header".to_string())?;
        let magic = u32::from_le_bytes(ghdr[0..4].try_into().unwrap());
        let le = magic == 0xa1b2_c3d4 || magic == 0xa1b2_3c4d;
        if !le && magic != 0xd4c3_b2a1 && magic != 0x4d3c_b2a1 {
            return Err("Unsupported PCAP magic".into());
        }

        let mut rhdr = [0u8; 16];
        let mut frame = vec![0u8; 65_536];
        let mut scanned: usize = 0;
        let mut pairs: BTreeMap<String, EchoPairStats> = BTreeMap::new();

        while scanned < pkt_cap && f.read_exact(&mut rhdr).is_ok() {
            let incl_len = if le {
                u32::from_le_bytes(rhdr[8..12].try_into().unwrap()) as usize
            } else {
                u32::from_be_bytes(rhdr[8..12].try_into().unwrap()) as usize
            };
            if incl_len > frame.len() {
                return Err("Frame exceeds 64 KiB cap".into());
            }
            f.read_exact(&mut frame[..incl_len]).map_err(|e| e.to_string())?;
            scanned += 1;

            if incl_len >= 42 && u16::from_be_bytes([frame[12], frame[13]]) == 0x0800 && frame[23] == 1 {
                let ihl = ((frame[14] & 0x0f) as usize) * 4;
                if ihl >= 20 && incl_len >= 14 + ihl + 8 {
                    let icmp_type = frame[14 + ihl];
                    if icmp_type == 0 || icmp_type == 8 {
                        let src = Ipv4Addr::new(frame[26], frame[27], frame[28], frame[29]);
                        let dst = Ipv4Addr::new(frame[30], frame[31], frame[32], frame[33]);
                        let data_len = incl_len - (14 + ihl + 8);
                        let entry = pairs.entry(format!("{src} -> {dst}")).or_default();
                        entry.echo_packets += 1;
                        entry.max_payload_bytes = entry.max_payload_bytes.max(data_len);
                    }
                }
            }
        }

        let mut out = serde_json::to_string_pretty(&serde_json::json!({
            "packets_scanned": scanned,
            "echo_flows": pairs,
            "raw_icmp_data": "[REDACTED]"
        }))
        .map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "ICMP profile scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
