package uvsdist

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	maxUvBytes  = 4 * 1024 * 1024
	maxOutBytes = 24 * 1024
)

var authRe = regexp.MustCompile(`(?i)(https?://)([^/@\s"']+@)`)

type SdistOnlyPkg struct {
	Name    string `json:"name"`
	Version string `json:"version"`
	Sdist   string `json:"sdist_info"`
}

func AuditUvSdistOnlyPackages(ctx context.Context, workspaceDir string, projectName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if projectName == "" || strings.ContainsAny(projectName, "/\\") || strings.Contains(projectName, "..") {
		return "", errors.New("invalid project directory name")
	}

	root, err := os.OpenRoot(workspaceDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	rel := filepath.Join(projectName, "uv.lock")
	fi, err := root.Lstat(rel)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxUvBytes {
		return "", errors.New("uv.lock missing, symlinked, or exceeds 4 MiB")
	}
	f, err := root.Open(rel)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var sdistOnly []SdistOnlyPkg
	var name, ver, sdistLine string
	hasWheel := false

	flush := func() {
		if name != "" && sdistLine != "" && !hasWheel {
			safe := authRe.ReplaceAllString(sdistLine, "${1}[REDACTED]@")
			sdistOnly = append(sdistOnly, SdistOnlyPkg{name, ver, safe})
		}
		name, ver, sdistLine = "", "", ""
		hasWheel = false
	}

	sc := bufio.NewScanner(io.LimitReader(f, maxUvBytes))
	for sc.Scan() {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		line := strings.TrimSpace(sc.Text())
		if line == "[[package]]" {
			flush()
			continue
		}
		switch {
		case strings.HasPrefix(line, "name = "):
			name = strings.Trim(strings.TrimPrefix(line, "name = "), `"`)
		case strings.HasPrefix(line, "version = "):
			ver = strings.Trim(strings.TrimPrefix(line, "version = "), `"`)
		case strings.HasPrefix(line, "sdist = "):
			sdistLine = line
		case strings.HasPrefix(line, "wheels = ["):
			hasWheel = line != "wheels = []"
		}
	}
	flush()
	if err := sc.Err(); err != nil {
		return "", err
	}

	out, err := json.MarshalIndent(map[string]any{
		"project":          projectName,
		"sdist_only_count": len(sdistOnly),
		"packages":         sdistOnly,
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
