use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_BIN_BYTES: u64 = 32 * 1024 * 1024;
const MH_MAGIC_64: u32 = 0xfeed_facf;
const FAT_MAGIC: u32 = 0xcafe_babe;
const LC_CODE_SIGNATURE: u32 = 0x0000_001d;

#[derive(Deserialize)]
pub struct MachoSigScanArgs {
    pub binary_name: String,
}

#[derive(Serialize)]
pub struct SliceInfo {
    pub cputype: u32,
    pub has_code_signature: bool,
}

fn inspect_macho64_slice(slice: &[u8]) -> Result<SliceInfo, String> {
    if slice.len() < 32 {
        return Err("Truncated Mach-O 64 header".into());
    }
    let magic = u32::from_le_bytes(slice[0..4].try_into().unwrap());
    if magic != MH_MAGIC_64 {
        return Err("Unsupported non-64-bit Mach-O slice".into());
    }
    let cputype = u32::from_le_bytes(slice[4..8].try_into().unwrap());
    let ncmds = u32::from_le_bytes(slice[16..20].try_into().unwrap()).min(256) as usize;
    let mut pos: usize = 32;
    let mut signed = false;

    for _ in 0..ncmds {
        if pos + 8 > slice.len() {
            break;
        }
        let cmd = u32::from_le_bytes(slice[pos..pos + 4].try_into().unwrap());
        let cmdsize = u32::from_le_bytes(slice[pos + 4..pos + 8].try_into().unwrap()) as usize;
        if cmdsize < 8 || pos + cmdsize > slice.len() {
            break;
        }
        if cmd == LC_CODE_SIGNATURE {
            signed = true;
        }
        pos += cmdsize;
    }
