pub async fn scan_macho_code_signature_header(sandbox: PathBuf, args: MachoSigScanArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.binary_name.is_empty() || args.binary_name.contains('/') || args.binary_name.contains("..") {
            return Err("Invalid binary filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.binary_name);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Binary missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_BIN_BYTES {
            return Err("Symlinked, special, or oversized binary".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut data: Vec<u8> = Vec::new();
        f.read_to_end(&mut data).map_err(|e| e.to_string())?;
        if data.len() < 8 {
