        }

        let mut slices: Vec<SliceInfo> = Vec::new();
        if u32::from_be_bytes(data[0..4].try_into().unwrap()) == FAT_MAGIC {
            let narch = u32::from_be_bytes(data[4..8].try_into().unwrap()).min(8) as usize;
