                if aoff + 20 > data.len() {
                    break;
                }
                let offset = u32::from_be_bytes(data[aoff + 8..aoff + 12].try_into().unwrap()) as usize;
                let size = u32::from_be_bytes(data[aoff + 12..aoff + 16].try_into().unwrap()) as usize;
