            }
        } else {
            slices.push(inspect_macho64_slice(&data)?);
        }

        serde_json::to_string_pretty(&slices).map_err(|e| e.to_string())
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "Mach-O signature scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
