import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
)

const maxJweBytes = 16384

var strongEncAlgs = map[string]bool{
	"A128GCM":       true,
	"A192GCM":       true,
	"A256GCM":       true,
	"XC20P":         true,
	"A256CBC-HS512": true,
}

type JweHeaderDiag struct {
	Alg          string   `json:"alg"`
	Enc          string   `json:"enc"`
	Kid          string   `json:"kid,omitempty"`
	Warnings     []string `json:"warnings"`
	EncryptedKey string   `json:"encrypted_key"`
	Ciphertext   string   `json:"ciphertext"`
	AuthTag      string   `json:"auth_tag"`
}

func DiagnoseCompactJwe(compactJwe string) (string, error) {
	if len(compactJwe) < 16 || len(compactJwe) > maxJweBytes {
		return "", errors.New("JWE length out of bounds (token redacted)")
	}
	segs := strings.Split(strings.TrimSpace(compactJwe), ".")
	if len(segs) != 5 {
		return "", errors.New("expected 5-segment compact JWE (token redacted)")
	}

	hdrJson, err := base64.RawURLEncoding.DecodeString(segs[0])
	if err != nil {
		return "", errors.New("malformed JWE protected header base64url (token redacted)")
	}
	var hdr struct {
		Alg string `json:"alg"`
		Enc string `json:"enc"`
		Kid string `json:"kid"`
		Zip string `json:"zip"`
		Jku string `json:"jku"`
	}
	if err := json.Unmarshal(hdrJson, &hdr); err != nil {
		return "", errors.New("malformed JWE header JSON (token redacted)")
	}

	var warns []string
	if hdr.Alg == "RSA1_5" {
		warns = append(warns, "CRITICAL_DEPRECATED_RSA1_5_ORACLE_RISK")
	}
	if hdr.Alg == "dir" && hdr.Kid == "" {
		warns = append(warns, "DIRECT_ENCRYPTION_MISSING_KID")
	}
	if !strongEncAlgs[hdr.Enc] {
		warns = append(warns, "UNAPPROVED_OR_WEAK_CONTENT_ENC")
	}
	if hdr.Zip != "" {
		warns = append(warns, "JWE_COMPRESSION_ENABLED_SIDECHANNEL_RISK")
	}
	if hdr.Jku != "" {
		warns = append(warns, "EXTERNAL_JKU_URL_IN_HEADER")
	}

	diag := JweHeaderDiag{
		Alg:          hdr.Alg,
		Enc:          hdr.Enc,
		Kid:          hdr.Kid,
		Warnings:     warns,
		EncryptedKey: "[REDACTED]",
		Ciphertext:   "[REDACTED]",
		AuthTag:      "[REDACTED]",
	}
	out, err := json.MarshalIndent(diag, "", "  ")
	if err != nil {
		return "", err
	}
	return string(out), nil
}
