use regex::Regex;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_LOCK_BYTES: u64 = 8 * 1024 * 1024;
const MAX_OUT_BYTES: usize = 32_768;

#[derive(Deserialize)]
pub struct NpmBundleAuditArgs {
    pub repo_dir: String,
}

#[derive(Deserialize)]
struct NpmPkgEntry {
    #[serde(rename = "inBundle", default)]
    in_bundle: bool,
    #[serde(default)]
    deprecated: Option<String>,
    #[serde(default)]
    resolved: Option<String>,
}

#[derive(Deserialize)]
struct NpmLockV3 {
    #[serde(default)]
    packages: BTreeMap<String, NpmPkgEntry>,
}

#[derive(Serialize)]
pub struct NpmBundleFinding {
    pub path: String,
    pub kind: &'static str,
    pub detail: String,
}

pub async fn audit_npm_bundled_and_deprecated(workspace: PathBuf, args: NpmBundleAuditArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.repo_dir.is_empty() || args.repo_dir.contains('/') || args.repo_dir.contains("..") {
            return Err("Invalid repository folder".into());
        }
        let canon_root = workspace.canonicalize().map_err(|_| "Workspace root missing".to_string())?;
        let target = canon_root.join(&args.repo_dir).join("package-lock.json");
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "package-lock.json missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_LOCK_BYTES {
            return Err("Symlinked, special, or oversized package-lock.json".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut raw = String::new();
        f.read_to_string(&mut raw).map_err(|e| e.to_string())?;
        let doc: NpmLockV3 = serde_json::from_str(&raw).map_err(|_| "Malformed package-lock.json".to_string())?;
        let cred_re = Regex::new(r"(?i)(https?://)([^/@\s]+@)").unwrap();
        let mut findings: Vec<NpmBundleFinding> = Vec::new();

        for (pkg_path, entry) in doc.packages {
            if pkg_path.is_empty() {
                continue;
            }
            if entry.in_bundle {
                let src = entry.resolved.unwrap_or_default();
                findings.push(NpmBundleFinding {
                    path: pkg_path.clone(),
                    kind: "IN_BUNDLE_UNPINNED_SUBPACKAGE",
                    detail: cred_re.replace_all(&src, "${1}[REDACTED]@").into_owned(),
                });
            }
            if let Some(dep_msg) = entry.deprecated {
                findings.push(NpmBundleFinding {
                    path: pkg_path,
                    kind: "DEPRECATED_PACKAGE",
                    detail: cred_re.replace_all(&dep_msg, "${1}[REDACTED]@").chars().take(160).collect(),
                });
            }
        }

        let mut out = serde_json::to_string_pretty(&findings).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "package-lock.json bundle audit timed out".to_string())?
        .map_err(|e| e.to_string())?
}
