use std::path::PathBuf;
use tokio::time::{timeout, Duration};
use x509_parser::pem::parse_x509_pem;
use x509_parser::prelude::*;

const MAX_CERT_BYTES: u64 = 262_144;
const OID_CT_PRECERT_SCTS: &str = "1.3.6.1.4.1.11129.2.4.2";
const OID_TLS_FEATURE: &str = "1.3.6.1.5.5.7.1.24";

#[derive(Deserialize)]
pub struct CtMustStapleArgs {
    pub cert_file: String,
}

#[derive(Serialize)]
pub struct CtMustStapleReport {
    pub subject: String,
    pub has_embedded_scts: bool,
    pub has_ocsp_must_staple_ext: bool,
    pub private_key_redacted: bool,
}

pub async fn check_cert_ct_and_must_staple(sandbox: PathBuf, args: CtMustStapleArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.cert_file.is_empty() || args.cert_file.contains('/') || args.cert_file.contains("..") {
            return Err("Invalid certificate filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.cert_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Certificate missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_CERT_BYTES {
            return Err("Symlinked, special, or oversized certificate".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut raw: Vec<u8> = Vec::new();
        f.read_to_end(&mut raw).map_err(|e| e.to_string())?;

        let has_priv = String::from_utf8_lossy(&raw).contains("PRIVATE KEY");
        let der = if raw.starts_with(b"-----") {
            let (_, pem_obj) = parse_x509_pem(&raw).map_err(|_| "Malformed PEM certificate".to_string())?;
            pem_obj.contents
        } else {
            raw
        };

        let (_, cert) = X509Certificate::from_der(&der).map_err(|_| "Malformed X.509 DER".to_string())?;
        let mut has_scts = false;
        let mut has_tls_feat = false;
        for ext in cert.extensions() {
            let oid_str = ext.oid.to_id_string();
            if oid_str == OID_CT_PRECERT_SCTS && !ext.value.is_empty() {
                has_scts = true;
            }
            if oid_str == OID_TLS_FEATURE && !ext.value.is_empty() {
                has_tls_feat = true;
            }
        }

        let rep = CtMustStapleReport {
            subject: cert.subject().to_string(),
            has_embedded_scts: has_scts,
            has_ocsp_must_staple_ext: has_tls_feat,
            private_key_redacted: has_priv,
        };
        serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "Certificate extension check timed out".to_string())?
        .map_err(|e| e.to_string())?
}
