package zeekx509

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"strings"
	"time"
)

const (
	maxLogBytes = 8 * 1024 * 1024
	maxOutBytes = 24 * 1024
)

type ZeekCertEntry struct {
	Fingerprint string   `json:"fingerprint"`
	Subject     string   `json:"certificate.subject"`
	Issuer      string   `json:"certificate.issuer"`
	KeyAlg      string   `json:"certificate.key_alg"`
	SigAlg      string   `json:"certificate.sig_alg"`
	KeyLength   int      `json:"certificate.key_length"`
	SanDns      []string `json:"san.dns"`
}

func InspectZeekWeakCerts(ctx context.Context, zeekDir string, logFile string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(logFile, ".jsonl") || strings.ContainsAny(logFile, "/\\") || strings.Contains(logFile, "..") {
		return "", errors.New("invalid Zeek x509 .jsonl filename")
	}

	root, err := os.OpenRoot(zeekDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(logFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxLogBytes {
		return "", errors.New("x509.log missing, symlinked, or exceeds 8 MiB")
	}
	f, err := root.Open(logFile)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var weak []map[string]any
	sc := bufio.NewScanner(io.LimitReader(f, maxLogBytes))
	sc.Buffer(make([]byte, 64*1024), 256*1024)

	for sc.Scan() {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		var rec ZeekCertEntry
		if err := json.Unmarshal(sc.Bytes(), &rec); err != nil {
			continue
		}
		sigLc := strings.ToLower(rec.SigAlg)
		kalgLc := strings.ToLower(rec.KeyAlg)
		weakerRsa := strings.Contains(kalgLc, "rsa") && rec.KeyLength > 0 && rec.KeyLength < 2048
		weakerSig := strings.Contains(sigLc, "sha1") || strings.Contains(sigLc, "md5")
		if weakerRsa || weakerSig {
			weak = append(weak, map[string]any{
				"fingerprint": rec.Fingerprint,
				"subject":     rec.Subject,
				"sig_alg":     rec.SigAlg,
				"key_length":  rec.KeyLength,
				"san_dns":     rec.SanDns,
				"san_email":   "[REDACTED]",
			})
			if len(weak) >= 150 {
				break
			}
		}
	}
	if err := sc.Err(); err != nil {
		return "", err
	}

	out, err := json.MarshalIndent(map[string]any{"weak_count": len(weak), "certificates": weak}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(out), nil
}
