}

pub fn query_pgaudit_sqlite(sandbox: &Path, q: PgAuditQuery) -> Result<String, String> {
    if !matches!(q.audit_class.as_str(), "DDL" | "ROLE" | "MISC") {
        return Err("audit_class must be DDL, ROLE, or MISC".into());
    }
    let db_path = check_pgaudit_db(sandbox, &q.db_file)?;
    let uri = format!("file:{}?mode=ro", db_path.display());
    let flags = OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_URI | OpenFlags::SQLITE_OPEN_NO_MUTEX;
    let conn = Connection::open_with_flags(uri, flags).map_err(|e| e.to_string())?;
    conn.busy_timeout(Duration::from_millis(800)).map_err(|e| e.to_string())?;

    let deadline = Instant::now() + Duration::from_secs(3);
    conn.progress_handler(1000, Some(move || Instant::now() > deadline));

    let pw_re = Regex::new(r"(?i)(PASSWORD\s+)'[^']*'").unwrap();
    let cap = q.limit.clamp(1, 150);

    let mut stmt = conn
        .prepare(
            "SELECT ts_epoch, db_user, audit_class, object_name, statement \
             FROM pgaudit_logs WHERE audit_class = ?1 AND db_user = ?2 \
             ORDER BY ts_epoch DESC LIMIT ?3",
        )
        .map_err(|e| e.to_string())?;

    let iter = stmt
        .query_map(params![q.audit_class, q.db_user, cap], |row| {
            let sql_stmt: String = row.get::<_, Option<String>>(4)?.unwrap_or_default();
            Ok(PgAuditEvent {
                ts_epoch: row.get(0)?,
                db_user: row.get(1)?,
                audit_class: row.get(2)?,
                object_name: row.get(3)?,
                redacted_statement: pw_re.replace_all(&sql_stmt, "${1}'[REDACTED]'").into_owned(),
            })
        })
        .map_err(|e| e.to_string())?;

    let mut out_rows: Vec<PgAuditEvent> = Vec::new();
    for item in iter {
