    }
    let mut json = serde_json::to_string_pretty(&out_rows).map_err(|e| e.to_string())?;
    if json.len() > MAX_OUT_BYTES {
        json.truncate(MAX_OUT_BYTES);
        json.push_str("\n...[TRUNCATED]");
    }
    Ok(json)
}
