import { lstat, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_WASM_BYTES = 8 * 1024 * 1024;
const MAX_OUT_BYTES = 16_384;

const WasmExportSchema = {
  wasmFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.wasm$/),
};

function readUleb(buf: Buffer, state: { pos: number }): number {
  let res = 0;
  let shift = 0;
  for (let i = 0; i < 5; i++) {
    if (state.pos >= buf.length) throw new Error("Truncated LEB128");
    const b = buf[state.pos++];
    res |= (b & 0x7f) << shift;
    if ((b & 0x80) === 0) return res >>> 0;
    shift += 7;
  }
  throw new Error("Oversized LEB128");
}

function readName(buf: Buffer, state: { pos: number }): string {
  const len = readUleb(buf, state);
  if (len > 256 || state.pos + len > buf.length) throw new Error("Invalid WASM UTF-8 name");
  const s = buf.subarray(state.pos, state.pos + len).toString("utf8");
  state.pos += len;
  return s;
