package tarstatic

import (
	"archive/tar"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path"
	"strings"
	"time"
)

const (
	maxTarBytes = 32 * 1024 * 1024
	maxMembers  = 5000
	maxOutBytes = 24 * 1024
)

type TarHeaderIssue struct {
	Name   string   `json:"name"`
	Issues []string `json:"issues"`
}

func ScanTarHeadersStatic(ctx context.Context, uploadDir string, tarName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(tarName, ".tar") || strings.ContainsAny(tarName, "/\\") || strings.Contains(tarName, "..") {
		return "", errors.New("invalid .tar filename")
	}

	root, err := os.OpenRoot(uploadDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(tarName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxTarBytes {
		return "", errors.New("tar archive missing, symlinked, or exceeds 32 MiB")
	}
	f, err := root.Open(tarName)
	if err != nil {
		return "", err
	}
	defer f.Close()

	tr := tar.NewReader(io.LimitReader(f, maxTarBytes))
	var findings []TarHeaderIssue
	seen := 0

	for {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return "", errors.New("corrupt tar header")
		}
		seen++
		if seen > maxMembers {
			return "", errors.New("tar archive exceeds 5000-member limit")
		}

		var issues []string
		clean := path.Clean(hdr.Name)
		if strings.HasPrefix(hdr.Name, "/") || strings.HasPrefix(clean, "..") {
			issues = append(issues, "TAR_SLIP_PATH_TRAVERSAL")
		}
		if hdr.Typeflag == tar.TypeSymlink || hdr.Typeflag == tar.TypeLink {
			dest := path.Clean(path.Join(path.Dir(clean), hdr.Linkname))
			if strings.HasPrefix(hdr.Linkname, "/") || strings.HasPrefix(dest, "..") {
				issues = append(issues, "ESCAPING_LINK_TARGET")
			}
		}
		if hdr.Typeflag == tar.TypeChar || hdr.Typeflag == tar.TypeBlock || hdr.Typeflag == tar.TypeFifo {
			issues = append(issues, "DEVICE_OR_FIFO_NODE")
		}
		if (hdr.Mode & 0o6000) != 0 {
			issues = append(issues, "SETUID_OR_SETGID_MODE")
		}
		if len(issues) > 0 && len(findings) < 200 {
			findings = append(findings, TarHeaderIssue{hdr.Name, issues})
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"members_scanned": seen,
		"findings_count":  len(findings),
		"findings":        findings,
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
