use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Path, PathBuf};
use std::process::Stdio;
use tokio::process::Command;
use tokio::time::{timeout, Duration};

const MAX_OUT_BYTES: usize = 24_576;

#[derive(Deserialize)]
pub struct RoutingPcapArgs {
    pub pcap_file: String,
    pub max_packets: u32,
}

#[derive(Serialize)]
pub struct RoutingSummary {
    pub peer_events: BTreeMap<String, usize>,
    pub auth_digests: &'static str,
}

fn verify_pcap(sandbox: &Path, name: &str) -> Result<PathBuf, String> {
    if !(name.ends_with(".pcap") || name.ends_with(".pcapng")) || name.contains('/') || name.contains("..") {
        return Err("Invalid PCAP filename".into());
    }
    let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
    let target = canon_root.join(name);
    let meta = std::fs::symlink_metadata(&target).map_err(|_| "PCAP file missing".to_string())?;
    if meta.file_type().is_symlink() || !meta.is_file() {
        return Err("Symlinked or special files forbidden".into());
    }
    let _probe = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&target)
        .map_err(|e| e.to_string())?;
    let resolved = target.canonicalize().map_err(|_| "Canonicalize failed".to_string())?;
    if resolved.parent() != Some(canon_root.as_path()) {
        return Err("PCAP escaped sandbox".into());
    }
    Ok(resolved)
}

pub async fn summarize_routing_control_plane(sandbox: &Path, args: RoutingPcapArgs) -> Result<String, String> {
    let pcap = verify_pcap(sandbox, &args.pcap_file)?;
    let cap = args.max_packets.clamp(1, 5000);

    let mut cmd = Command::new("/usr/bin/tshark");
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", "/nonexistent")
        .args([
            "-n",
            "-r",
            &pcap.to_string_lossy(),
            "-c",
            &cap.to_string(),
            "-Y",
            "bgp || ospf",
            "-T",
            "fields",
            "-E",
            "separator=\t",
            "-e",
            "ip.src",
            "-e",
            "ip.dst",
            "-e",
            "bgp.type",
            "-e",
            "ospf.msg",
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let out = timeout(Duration::from_secs(5), cmd.output())
        .await
        .map_err(|_| "tshark routing scan timed out".to_string())?
        .map_err(|e| format!("Spawn error: {e}"))?;
    if !out.status.success() {
        return Err(format!("tshark returned {:?}", out.status.code()));
    }

    let mut peer_events: BTreeMap<String, usize> = BTreeMap::new();
    for line in String::from_utf8_lossy(&out.stdout).lines() {
        let cols: Vec<&str> = line.split('\t').collect();
        if cols.len() >= 4 && !cols[0].is_empty() {
            let proto_tag = if !cols[2].is_empty() {
                format!("bgp_type={}", cols[2])
            } else {
                format!("ospf_msg={}", cols[3])
            };
            let key = format!("{} -> {} [{}]", cols[0], cols[1], proto_tag);
            *peer_events.entry(key).or_insert(0) += 1;
        }
    }

    let summary = RoutingSummary {
        peer_events,
        auth_digests: "[REDACTED]",
    };
    let mut json = serde_json::to_string_pretty(&summary).map_err(|e| e.to_string())?;
    if json.len() > MAX_OUT_BYTES {
        json.truncate(MAX_OUT_BYTES);
    }
    Ok(json)
}
