package pcaptunproto

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"strings"
	"time"
)

const (
	maxSnapBytes = 262144
	maxOutBytes  = 16384
)

type EncapScanArgs struct {
	PcapFile   string `json:"pcap_file"`
	MaxPackets int    `json:"max_packets"`
}

func protoLabel(p byte) (string, bool) {
	switch p {
	case 4:
		return "IP-in-IP", true
	case 41:
		return "IPv6-in-IPv4", true
	case 47:
		return "GRE", true
	default:
		return "", false
	}
}

func DetectIpEncapsulationTunnels(ctx context.Context, pcapDir string, args EncapScanArgs) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(args.PcapFile, ".pcap") || strings.ContainsAny(args.PcapFile, "/\\") || strings.Contains(args.PcapFile, "..") {
		return "", errors.New("invalid .pcap filename")
	}
	pktCap := args.MaxPackets
	if pktCap <= 0 || pktCap > 10000 {
		pktCap = 3000
	}

	root, err := os.OpenRoot(pcapDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.PcapFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("PCAP missing, symlinked, or non-regular")
	}
	f, err := root.Open(args.PcapFile)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var ghdr [24]byte
	if _, err := io.ReadFull(f, ghdr[:]); err != nil {
		return "", errors.New("truncated PCAP header")
	}
	var bo binary.ByteOrder = binary.LittleEndian
	magic := binary.LittleEndian.Uint32(ghdr[0:4])
	if magic == 0xd4c3b2a1 || magic == 0x4d3cb2a1 {
		bo = binary.BigEndian
	} else if magic != 0xa1b2c3d4 && magic != 0xa1b23c4d {
		return "", errors.New("unsupported PCAP magic")
	}

	tunnels := make(map[string]int)
	var rhdr [16]byte
	buf := make([]byte, 65536)
	scanned := 0

	for scanned < pktCap {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		if _, err := io.ReadFull(f, rhdr[:]); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return "", err
		}
		inclLen := int(bo.Uint32(rhdr[8:12]))
		if inclLen < 0 || inclLen > maxSnapBytes {
			return "", errors.New("invalid incl_len")
		}
		if inclLen > len(buf) {
			buf = make([]byte, inclLen)
		}
		if _, err := io.ReadFull(f, buf[:inclLen]); err != nil {
			return "", err
		}
		scanned++

		if inclLen >= 34 && binary.BigEndian.Uint16(buf[12:14]) == 0x0800 {
			if label, ok := protoLabel(buf[23]); ok {
				src := net.IP(buf[26:30]).String()
				dst := net.IP(buf[30:34]).String()
				tunnels[fmt.Sprintf("%s -> %s (%s)", src, dst, label)]++
			}
		}
	}

	out, err := json.MarshalIndent(map[string]any{
		"packets_scanned": scanned,
		"tunnel_flows":    tunnels,
		"inner_payloads":  "[REDACTED]",
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
