func checkRegularInRoot(root *os.Root, canonRoot, name string) (string, error) {
	if name == "" || strings.ContainsAny(name, "/\\") || strings.Contains(name, "..") {
		return "", errors.New("invalid filename")
	}
	fi, err := root.Lstat(name)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("file missing, symlinked, or non-regular")
	}
	resolved, err := filepath.EvalSymlinks(filepath.Join(canonRoot, name))
	if err != nil || filepath.Dir(resolved) != canonRoot {
		return "", errors.New("path escaped sandbox")
	}
	return resolved, nil
}

func VerifyBlobWithCosignPub(ctx context.Context, sandboxDir string, args PubVerifyArgs) (string, error) {
	if !strings.HasSuffix(args.PubFile, ".pub") || !strings.HasSuffix(args.SigFile, ".sig") {
		return "", errors.New("pub_file must end with .pub and sig_file with .sig")
	}

	root, err := os.OpenRoot(sandboxDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	canonRoot, err := filepath.EvalSymlinks(sandboxDir)
	if err != nil {
		return "", err
	}
	pubPath, err := checkRegularInRoot(root, canonRoot, args.PubFile)
	if err != nil {
		return "", err
	}
	sigPath, err := checkRegularInRoot(root, canonRoot, args.SigFile)
	if err != nil {
		return "", err
	}
	artPath, err := checkRegularInRoot(root, canonRoot, args.ArtifactFile)
	if err != nil {
		return "", err
	}

	kf, err := root.Open(args.PubFile)
	if err != nil {
		return "", err
	}
	kb, _ := io.ReadAll(io.LimitReader(kf, 32768))
	kf.Close()
	if bytes.Contains(kb, []byte("PRIVATE KEY")) || !bytes.Contains(kb, []byte("BEGIN PUBLIC KEY")) {
		return "", errors.New("key file rejected: not a public PEM key (private material redacted)")
	}

	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	argv := []string{
		"verify-blob",
		"--offline=true",
		"--key", pubPath,
		"--signature", sigPath,
		"--", artPath,
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/cosign", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "HOME=/nonexistent"}
	var combined bytes.Buffer
	cmd.Stdout = &combined
	cmd.Stderr = &combined

	runErr := cmd.Run()
	detail := combined.String()
	if len(detail) > maxOutBytes {
		detail = detail[:maxOutBytes]
	}
	out, err := json.MarshalIndent(map[string]any{
		"artifact": args.ArtifactFile,
		"verified": runErr == nil,
		"detail":   detail,
	}, "", "  ")
	return string(out), err
}
