        let target = canon_root.join(&args.bom_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "SBOM missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_SBOM_BYTES {
            return Err("Symlinked, special, or oversized SBOM".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut raw = String::new();
        f.read_to_string(&mut raw).map_err(|e| e.to_string())?;
        let doc: CdxDoc = serde_json::from_str(&raw).map_err(|_| "Invalid CycloneDX JSON".to_string())?;
        let cred_re = Regex::new(r"(?i)(https?://)([^/@\s]+@)").unwrap();

        let mut violations: Vec<NonCompliantComponent> = Vec::new();
        for c in doc.components {
            let mut ids: Vec<String> = Vec::new();
            for choice in &c.licenses {
                if let Some(lic) = &choice.license {
                    if !lic.id.is_empty() {
                        ids.push(lic.id.clone());
                    } else if !lic.name.is_empty() {
                        ids.push(lic.name.clone());
                    }
                } else if !choice.expression.is_empty() {
                    ids.push(choice.expression.clone());
                }
            }
            let ok = !ids.is_empty() && ids.iter().all(|id| APPROVED_LICENSES.contains(&id.as_str()));
            if !ok && violations.len() < 200 {
