        }

        let mut out = serde_json::to_string_pretty(&violations).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "License gate scan timed out".to_string())?
        .map_err(|e| e.to_string())?
}
