const MAX_ELF_BYTES: u64 = 16 * 1024 * 1024;
const SHT_SYMTAB: u32 = 2;
const SHT_NOTE: u32 = 7;
const NT_GNU_BUILD_ID: u32 = 3;

#[derive(Deserialize)]
pub struct ElfBuildIdArgs {
    pub binary_name: String,
