            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut buf: Vec<u8> = Vec::new();
        f.read_to_end(&mut buf).map_err(|e| e.to_string())?;

        if buf.len() < 64 || buf[0..4] != [0x7f, b'E', b'L', b'F'] || buf[4] != 2 || buf[5] != 1 {
            return Err("Expected little-endian 64-bit ELF".into());
        }
        let sh_off = u64::from_le_bytes(buf[40..48].try_into().unwrap()) as usize;
        let sh_entsize = u16::from_le_bytes([buf[58], buf[59]]) as usize;
        let sh_num = u16::from_le_bytes([buf[60], buf[61]]) as usize;
        if sh_entsize < 64 || sh_num > 512 || sh_off.saturating_add(sh_entsize * sh_num) > buf.len() {
            return Err("Invalid ELF64 section table".into());
        }

        let mut has_symtab = false;
        let mut build_id: Option<String> = None;

        for i in 0..sh_num {
            let sh = sh_off + i * sh_entsize;
            let sh_type = u32::from_le_bytes(buf[sh + 4..sh + 8].try_into().unwrap());
            if sh_type == SHT_SYMTAB {
                has_symtab = true;
            } else if sh_type == SHT_NOTE && build_id.is_none() {
                let noff = u64::from_le_bytes(buf[sh + 24..sh + 32].try_into().unwrap()) as usize;
                let nsz = u64::from_le_bytes(buf[sh + 32..sh + 40].try_into().unwrap()) as usize;
                if noff.saturating_add(nsz) <= buf.len() && nsz >= 16 {
                    let slice = &buf[noff..noff + nsz];
                    let namesz = u32::from_le_bytes(slice[0..4].try_into().unwrap()) as usize;
                    let descsz = u32::from_le_bytes(slice[4..8].try_into().unwrap()) as usize;
