use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use subtle::ConstantTimeEq;
use tokio::time::{timeout, Duration};

const MAX_LEAF_BYTES: u64 = 16 * 1024 * 1024;

#[derive(Deserialize)]
pub struct ProofStep {
    pub sibling_hex: String,
    pub sibling_on_left: bool,
}

#[derive(Deserialize)]
pub struct InclusionProofArgs {
    pub artifact_file: String,
    pub expected_root_hex: String,
    pub audit_path: Vec<ProofStep>,
}

#[derive(Serialize)]
pub struct InclusionProofReport {
    pub artifact: String,
    pub depth: usize,
    pub verified: bool,
}

pub async fn verify_rfc6962_inclusion_proof(sandbox: PathBuf, args: InclusionProofArgs) -> Result<String, String> {
    if args.audit_path.len() > 64 {
        return Err("Merkle audit_path exceeds maximum depth of 64".into());
    }
    let expected_root = hex::decode(&args.expected_root_hex).map_err(|_| "Invalid expected_root_hex".to_string())?;
    if expected_root.len() != 32 {
        return Err("Expected 32-byte SHA-256 Merkle root".into());
    }

    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if args.artifact_file.is_empty() || args.artifact_file.contains('/') || args.artifact_file.contains("..") {
            return Err("Invalid artifact filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.artifact_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Artifact missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_LEAF_BYTES {
            return Err("Symlinked, special, or oversized leaf artifact".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let mut leaf_hasher = Sha256::new();
        leaf_hasher.update([0x00u8]);
        let mut chunk = [0u8; 32_768];
        loop {
            let n = f.read(&mut chunk).map_err(|e| e.to_string())?;
            if n == 0 {
                break;
            }
            leaf_hasher.update(&chunk[..n]);
        }
        let mut current: [u8; 32] = leaf_hasher.finalize().into();

        for step in &args.audit_path {
            let sib = hex::decode(&step.sibling_hex).map_err(|_| "Malformed sibling hex".to_string())?;
            if sib.len() != 32 {
                return Err("Sibling hash must be 32 bytes".into());
            }
            let mut node_hasher = Sha256::new();
            node_hasher.update([0x01u8]);
            if step.sibling_on_left {
                node_hasher.update(&sib);
                node_hasher.update(current);
            } else {
                node_hasher.update(current);
                node_hasher.update(&sib);
            }
            current = node_hasher.finalize().into();
        }

        let ok = bool::from(current.ct_eq(&expected_root));
        let rep = InclusionProofReport {
            artifact: args.artifact_file,
            depth: args.audit_path.len(),
            verified: ok,
        };
        serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "Merkle inclusion verification timed out".to_string())?
        .map_err(|e| e.to_string())?
}
