package zeekrdp

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"strings"
	"time"
)

const (
	maxRdpLogBytes = 8 * 1024 * 1024
	maxOutBytes    = 24 * 1024
)

func InspectZeekRdpSecurity(ctx context.Context, zeekDir string, logName string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	if !strings.HasSuffix(logName, ".log") || strings.ContainsAny(logName, "/\\") || strings.Contains(logName, "..") {
		return "", errors.New("invalid Zeek rdp.log filename")
	}

	root, err := os.OpenRoot(zeekDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(logName)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxRdpLogBytes {
		return "", errors.New("rdp.log missing, symlinked, or exceeds 8 MiB")
	}
	f, err := root.Open(logName)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var fields []string
	var findings []map[string]string
	sc := bufio.NewScanner(io.LimitReader(f, maxRdpLogBytes))

	for sc.Scan() {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		line := sc.Text()
		if strings.HasPrefix(line, "#fields\t") {
			fields = strings.Split(line, "\t")[1:]
			continue
		}
		if strings.HasPrefix(line, "#") || len(fields) == 0 {
			continue
		}
		cols := strings.Split(line, "\t")
		if len(cols) != len(fields) {
			continue
		}
		row := make(map[string]string, len(fields))
		for i, k := range fields {
			row[k] = cols[i]
		}
		secProto := row["security_protocol"]
		res := row["result"]
		if secProto == "RDP" || strings.Contains(strings.ToLower(res), "fail") {
			findings = append(findings, map[string]string{
				"ts":                row["ts"],
				"orig_h":            row["id.orig_h"],
				"resp_h":            row["id.resp_h"],
				"security_protocol": secProto,
				"result":            res,
				"cookie":            "[REDACTED]",
			})
			if len(findings) >= 150 {
				break
			}
		}
	}
	if err := sc.Err(); err != nil {
		return "", err
	}

	out, err := json.MarshalIndent(map[string]any{"count": len(findings), "sessions": findings}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]) + "\n...[TRUNCATED]", nil
	}
	return string(out), nil
}
