const execFileAsync = promisify(execFile);
const MAX_OUT_BYTES = 24_576;

const Http2PcapSchema = {
  pcapFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.(pcap|pcapng)$/),
  maxPackets: z.number().int().min(1).max(4000).default(1500),
};

export function registerHttp2HeaderAnalyzer(server: McpServer, pcapDir = "/var/sandbox/pcaps"): void {
  server.tool("summarize_pcap_http2_requests", Http2PcapSchema, async ({ pcapFile, maxPackets }) => {
    const canonDir = await realpath(pcapDir);
    const candidate = path.join(canonDir, pcapFile);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile()) {
      throw new Error("PCAP file is symlinked or non-regular");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("PCAP escaped sandbox confinement");
    }

    const argv = [
      "-n",
      "-o",
      "tls.keylog_file:",
      "-r",
      resolved,
      "-c",
      String(maxPackets),
      "-Y",
      "http2.headers.method",
      "-T",
      "fields",
      "-E",
      "separator=\t",
      "-e",
      "ip.src",
      "-e",
      "http2.headers.method",
      "-e",
      "http2.headers.authority",
      "-e",
      "http2.headers.path",
    ];

    const { stdout } = await execFileAsync("/usr/bin/tshark", argv, {
      shell: false,
      timeout: 6000,
      killSignal: "SIGKILL",
      maxBuffer: 262_144,
      env: { PATH: "/usr/bin:/bin", HOME: "/nonexistent" },
    });

    const streams = stdout
      .split("\n")
      .filter(Boolean)
      .slice(0, 250)
      .map((line) => {
        const [src = "", method = "", auth = "", rawPath = ""] = line.split("\t");
        const basePath = rawPath.split("?")[0].slice(0, 200);
        return {
          src,
          method,
          authority: auth.slice(0, 253),
          path: rawPath.includes("?") ? `${basePath}?[REDACTED]` : basePath,
          cookiesAndAuth: "[REDACTED]",
        };
      });

    const out = JSON.stringify({ count: streams.length, streams }, null, 2);
    return { content: [{ type: "text", text: out.slice(0, MAX_OUT_BYTES) }] };
  });
}
