		return "", errors.New("certificate is missing or not marked IsCA=true")
	}

	var warnings []string
	if len(caCert.PermittedDNSDomains) == 0 {
		warnings = append(warnings, "UNCONSTRAINED_SUBORDINATE_CA_NO_PERMITTED_DNS")
	}
	if caCert.MaxPathLen < 0 && !caCert.MaxPathLenZero {
		warnings = append(warnings, "MISSING_MAX_PATH_LEN_CONSTRAINT")
	}

	out, err := json.MarshalIndent(map[string]any{
		"subject":               caCert.Subject.String(),
		"max_path_len":          caCert.MaxPathLen,
		"max_path_len_zero":     caCert.MaxPathLenZero,
