    const wantLen = algorithm === "sha256" ? 32 : 64;
    if (wantBuf.byteLength !== wantLen) {
      throw new Error(`Expected ${wantLen}-byte hex digest for ${algorithm}`);
    }

    const canonDir = await realpath(imgDir);
    const candidate = path.join(canonDir, imageName);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_IMAGE_BYTES) {
      throw new Error("Image file is symlinked, missing, or exceeds 128 MiB");
