      throw new Error("Image file escaped sandbox confinement");
    }

    const hasher = createHash(algorithm);
    const src = createReadStream(resolved, { highWaterMark: 65_536 });
    await pipeline(src, hasher, { signal: AbortSignal.timeout(5000) });

    const actualBuf = hasher.digest();
    const verified = actualBuf.byteLength === wantBuf.byteLength && timingSafeEqual(actualBuf, wantBuf);

    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(
            {
              image: imageName,
              bytesHashed: st.size,
              algorithm,
              verified,
              computedHex: actualBuf.toString("hex"),
            },
            null,
            2,
          ),
        },
      ],
    };
  });
}
