use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Read};
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_SCAN_BYTES: u64 = 8 * 1024 * 1024;
const MAX_OUT_BYTES: usize = 32_768;
const SCANNER_PREFIXES: &[&str] = &["sqlmap", "nikto", "nuclei", "masscan", "gobuster", "ffuf"];

#[derive(Deserialize)]
pub struct ZeekUaScanArgs {
    pub log_file: String,
}

#[derive(Serialize, Default)]
pub struct ScannerIpSummary {
    pub hits: usize,
    pub sample_paths: Vec<String>,
}

pub async fn detect_zeek_http_scanners(sandbox: PathBuf, args: ZeekUaScanArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !args.log_file.ends_with(".jsonl") || args.log_file.contains('/') || args.log_file.contains("..") {
            return Err("Invalid Zeek http .jsonl filename".into());
        }
        let canon_root = sandbox.canonicalize().map_err(|_| "Sandbox root missing".to_string())?;
        let target = canon_root.join(&args.log_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Log file missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return Err("Symlinks and special files forbidden".into());
        }
        let f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;

        let reader = BufReader::new(f.take(MAX_SCAN_BYTES));
        let mut offenders: BTreeMap<String, ScannerIpSummary> = BTreeMap::new();

        for line_res in reader.lines() {
            let line = line_res.map_err(|e| e.to_string())?;
            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
            let ua = v.get("user_agent").and_then(|u| u.as_str()).unwrap_or("").to_ascii_lowercase();
            if !SCANNER_PREFIXES.iter().any(|p| ua.contains(p)) {
                continue;
            }
            let src = v.get("id.orig_h").and_then(|s| s.as_str()).unwrap_or("").to_string();
            if src.is_empty() {
                continue;
            }
            let raw_uri = v.get("uri").and_then(|u| u.as_str()).unwrap_or("/");
            let base_path = raw_uri.split('?').next().unwrap_or("/").chars().take(120).collect();
            let entry = offenders.entry(src).or_default();
            entry.hits += 1;
            if entry.sample_paths.len() < 10 {
                entry.sample_paths.push(base_path);
            }
        }

        let mut out = serde_json::to_string_pretty(&serde_json::json!({
            "scanner_sources": offenders,
            "usernames_and_queries": "[REDACTED]"
        }))
        .map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
            out.push_str("\n...[TRUNCATED]");
        }
        Ok(out)
    });

    timeout(Duration::from_secs(3), job)
        .await
        .map_err(|_| "Zeek scanner hunt timed out".to_string())?
        .map_err(|e| e.to_string())?
}
