		return "", errors.New("invalid PCAP filename")
	}
	if args.MaxPackets <= 0 || args.MaxPackets > 5000 {
		args.MaxPackets = 2000
	}

	root, err := os.OpenRoot(pcapDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(args.PcapFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() {
		return "", errors.New("PCAP missing, non-regular, or symlinked")
	}
	canonRoot, err := filepath.EvalSymlinks(pcapDir)
	if err != nil {
		return "", err
	}
	canonPcap, err := filepath.EvalSymlinks(filepath.Join(canonRoot, args.PcapFile))
	if err != nil || filepath.Dir(canonPcap) != canonRoot {
		return "", errors.New("capture escaped sandbox")
