		"-n",
		"-r", canonPcap,
		"-c", strconv.Itoa(args.MaxPackets),
		"-Y", "icmpv6.type == 136 && icmpv6.nd.na.flag.o == 1",
		"-T", "fields",
		"-E", "separator=\t",
		"-e", "icmpv6.nd.na.target_address",
		"-e", "eth.src",
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/tshark", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "HOME=/nonexistent"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("tshark NDP scan failed or timed out")
	}

	targetMacs := make(map[string]map[string]struct{})
