        return Err("JWS length out of bounds (token redacted)".into());
    }
    let parts: Vec<&str> = args.compact_jws.trim().split('.').collect();
    if parts.len() != 3 {
        return Err("Expected 3-segment JWS (token redacted)".into());
    }

    let hdr_bytes = URL_SAFE_NO_PAD
        .decode(parts[0])
        .map_err(|_| "Malformed base64url JWS header (token redacted)".to_string())?;
    let hdr: serde_json::Value = serde_json::from_slice(&hdr_bytes)
        .map_err(|_| "Malformed JWS header JSON (token redacted)".to_string())?;

    let alg = hdr.get("alg").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let kid = hdr.get("kid").and_then(|v| v.as_str()).map(|s| s.chars().take(64).collect());
    let mut hazards: Vec<&'static str> = Vec::new();

    if alg.is_empty() || alg.eq_ignore_ascii_case("none") {
        hazards.push("CRITICAL_ALG_NONE");
    }
    if hdr.get("b64") == Some(&serde_json::Value::Bool(false)) {
        hazards.push("RFC7797_UNENCODED_PAYLOAD_B64_FALSE");
    }
    if hdr.get("jwk").is_some() {
        hazards.push("EMBEDDED_SELF_SIGNED_JWK_IN_HEADER");
    }
    if hdr.get("x5c").is_some() {
        hazards.push("EMBEDDED_X5C_CERT_CHAIN_IN_HEADER");
    }
    if hdr.get("jku").is_some() || hdr.get("x5u").is_some() {
        hazards.push("REMOTE_KEY_URL_SSRF_AND_SPOOF_RISK");
    }
    if hdr.get("crit").is_some() {
        hazards.push("CRITICAL_EXTENSION_HEADER_PRESENT");
    }
    if parts[1].is_empty() {
        hazards.push("DETACHED_EMPTY_PAYLOAD_SEGMENT");
    }

    let diag = JwsHeaderSecurityDiag {
        alg,
        kid,
        hazards,
        payload: "[REDACTED]",
        signature: "[REDACTED]",
    };
    serde_json::to_string_pretty(&diag).map_err(|e| e.to_string())
}
