var (
	allowedUnits = map[string]bool{"vault.service": true, "kubelet.service": true, "haproxy.service": true}
	secretRe     = regexp.MustCompile(`(?i)(bearer\s+[a-z0-9._~+/=-]+|(?:token|secret|password)=[^\s"']+)`)
