func InspectSystemdUnitLifecycle(ctx context.Context, args UnitLifecycleArgs) (string, error) {
	if !allowedUnits[args.Unit] {
		return "", errors.New("unit is not in the read-only allowlist")
	}
	if args.SinceMinutes <= 0 || args.SinceMinutes > 1440 {
		args.SinceMinutes = 60
	}
	if args.MaxEvents <= 0 || args.MaxEvents > 150 {
		args.MaxEvents = 50
	}

	ctx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	argv := []string{
		"--no-pager",
		"--quiet",
		"-o", "json",
		"_PID=1",
		"UNIT=" + args.Unit,
		fmt.Sprintf("--since=-%dm", args.SinceMinutes),
		"-n", strconv.Itoa(args.MaxEvents),
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/journalctl", argv...)
	cmd.Env = []string{"PATH=/usr/bin:/bin", "LC_ALL=C"}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", errors.New("journalctl lifecycle query failed or timed out")
	}

	var lifecycle []map[string]any
	for _, line := range strings.Split(stdout.String(), "\n") {
