			continue
		}
		var ev map[string]any
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			continue
		}
		msg, _ := ev["MESSAGE"].(string)
		lifecycle = append(lifecycle, map[string]any{
			"ts":          ev["__REALTIME_TIMESTAMP"],
			"job_result":  ev["JOB_RESULT"],
			"exit_status": ev["EXIT_STATUS"],
			"message":     secretRe.ReplaceAllString(msg, "[REDACTED]"),
		})
	}

	out, err := json.MarshalIndent(map[string]any{"unit": args.Unit, "events": lifecycle}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
