use regex::Regex;
use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::PathBuf;
use tokio::time::{timeout, Duration};

const MAX_YAML_BYTES: u64 = 262_144;
const MAX_OUT_BYTES: usize = 16_384;

#[derive(Deserialize)]
pub struct SelfHostedAuditArgs {
    pub workflow_file: String,
}

#[derive(Serialize)]
pub struct SelfHostedAuditReport {
    pub workflow: String,
    pub has_self_hosted_runner: bool,
    pub has_public_pr_or_comment_trigger: bool,
    pub critical_fork_runner_exposure: bool,
}

pub async fn audit_gha_self_hosted_exposure(repo_root: PathBuf, args: SelfHostedAuditArgs) -> Result<String, String> {
    let job = tokio::task::spawn_blocking(move || -> Result<String, String> {
        if !(args.workflow_file.ends_with(".yml") || args.workflow_file.ends_with(".yaml"))
            || args.workflow_file.contains('/')
            || args.workflow_file.contains("..")
        {
            return Err("Invalid workflow filename".into());
        }
        let wf_dir = repo_root
            .join(".github")
            .join("workflows")
            .canonicalize()
            .map_err(|_| ".github/workflows directory missing".to_string())?;
        let target = wf_dir.join(&args.workflow_file);
        let meta = std::fs::symlink_metadata(&target).map_err(|_| "Workflow missing".to_string())?;
        if meta.file_type().is_symlink() || !meta.is_file() || meta.len() > MAX_YAML_BYTES {
            return Err("Symlinked, special, or oversized workflow file".into());
        }
        let mut f = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|e| e.to_string())?;
        let mut raw = String::new();
        f.read_to_string(&mut raw).map_err(|e| e.to_string())?;

        let tok_re = Regex::new(r"(gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})").unwrap();
        let clean = tok_re.replace_all(&raw, "[REDACTED]");

        let self_hosted_re = Regex::new(r"(?i)runs-on\s*:[^\n]*self-hosted").unwrap();
        let pub_trig_re = Regex::new(r"(?m)^\s*(?:pull_request|pull_request_target|issue_comment)\s*:").unwrap();

        let has_sh = self_hosted_re.is_match(&clean);
        let has_pub = pub_trig_re.is_match(&clean);

        let rep = SelfHostedAuditReport {
            workflow: args.workflow_file,
            has_self_hosted_runner: has_sh,
            has_public_pr_or_comment_trigger: has_pub,
            critical_fork_runner_exposure: has_sh && has_pub,
        };
        let mut out = serde_json::to_string_pretty(&rep).map_err(|e| e.to_string())?;
        if out.len() > MAX_OUT_BYTES {
            out.truncate(MAX_OUT_BYTES);
        }
        Ok(out)
    });

    timeout(Duration::from_secs(2), job)
        .await
        .map_err(|_| "Self-hosted runner audit timed out".to_string())?
        .map_err(|e| e.to_string())?
}
