package wasmbounds

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"strings"
	"time"
)

const maxWasmBytes = 8 * 1024 * 1024

func readUleb32(b []byte, pos *int) (uint32, error) {
	var res uint32
	var shift uint
	for i := 0; i < 5; i++ {
		if *pos >= len(b) {
			return 0, errors.New("truncated LEB128")
		}
		c := b[*pos]
		*pos++
		res |= uint32(c&0x7f) << shift
		if c&0x80 == 0 {
			return res, nil
		}
		shift += 7
	}
	return 0, errors.New("LEB128 overflow")
}

func ScanWasmMemoryLimits(ctx context.Context, wasmDir string, wasmFile string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()

	if !strings.HasSuffix(wasmFile, ".wasm") || strings.ContainsAny(wasmFile, "/\\") || strings.Contains(wasmFile, "..") {
		return "", errors.New("invalid .wasm filename")
	}

	root, err := os.OpenRoot(wasmDir)
	if err != nil {
		return "", err
	}
	defer root.Close()

	fi, err := root.Lstat(wasmFile)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 || !fi.Mode().IsRegular() || fi.Size() > maxWasmBytes {
		return "", errors.New("WASM file missing, symlinked, or exceeds 8 MiB")
	}
	f, err := root.Open(wasmFile)
	if err != nil {
		return "", err
	}
	defer f.Close()

	data, err := io.ReadAll(io.LimitReader(f, maxWasmBytes))
	if err != nil {
		return "", err
	}
	if len(data) < 8 || data[0] != 0x00 || data[1] != 'a' || data[2] != 's' || data[3] != 'm' || data[4] != 1 {
		return "", errors.New("invalid WASM v1 binary magic")
	}

	type memInfo struct {
		InitialPages uint32  `json:"initial_pages"`
		MaxPages     *uint32 `json:"max_pages"`
		Unbounded    bool    `json:"unbounded"`
	}
	var memories []memInfo
	dataSectionBytes := 0
	pos := 8

	for pos < len(data) {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		secID := data[pos]
		pos++
		secLen, err := readUleb32(data, &pos)
		if err != nil || pos+int(secLen) > len(data) {
			return "", errors.New("malformed WASM section header")
		}
		secEnd := pos + int(secLen)
		if secID == 5 {
			sub := pos
			cnt, err := readUleb32(data, &sub)
			if err == nil {
				for i := uint32(0); i < cnt && sub < secEnd; i++ {
					flags, err := readUleb32(data, &sub)
					if err != nil {
						break
					}
					initP, _ := readUleb32(data, &sub)
					if (flags & 0x01) != 0 {
						maxP, _ := readUleb32(data, &sub)
						memories = append(memories, memInfo{initP, &maxP, false})
					} else {
						memories = append(memories, memInfo{initP, nil, true})
					}
				}
			}
		} else if secID == 11 {
			dataSectionBytes = int(secLen)
		}
		pos = secEnd
	}

	out, err := json.MarshalIndent(map[string]any{
		"wasm_file":          wasmFile,
		"memories":           memories,
		"data_section_bytes": dataSectionBytes,
		"data_segments":      "[REDACTED]",
	}, "", "  ")
	return string(out), err
}
