import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { lstat, open as fsOpen, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_HEADER_BYTES = 1_048_576;
const MAX_OUT_BYTES = 16_384;

const SafetensorsSchema = {
  modelFile: z.string().regex(/^[a-zA-Z0-9_.-]+\.safetensors$/),
};

export function registerSafetensorsStaticValidator(server: McpServer, modelDir = "/srv/sandbox/models"): void {
  server.tool("validate_safetensors_header_static", SafetensorsSchema, async ({ modelFile }) => {
    const canonDir = await realpath(modelDir);
    const candidate = path.join(canonDir, modelFile);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size < 8) {
      throw new Error("Safetensors file is symlinked, missing, or shorter than 8 bytes");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("Model file escaped sandbox confinement");
    }

    const fh = await fsOpen(resolved, "r");
    try {
      const lenBuf = Buffer.alloc(8);
      await fh.read(lenBuf, 0, 8, 0);
      const hdrLenBig = lenBuf.readBigUInt64LE(0);
      if (hdrLenBig === 0n || hdrLenBig > BigInt(MAX_HEADER_BYTES)) {
        throw new Error(`Safetensors JSON header exceeds 1 MiB cap (${hdrLenBig.toString()} bytes)`);
      }
      const hdrLen = Number(hdrLenBig);
      if (8 + hdrLen > st.size) {
        throw new Error("Safetensors header length exceeds total file size");
      }

      const hdrBuf = Buffer.alloc(hdrLen);
      await fh.read(hdrBuf, 0, hdrLen, 8);
      const parsed = JSON.parse(hdrBuf.toString("utf8")) as Record<string, any>;
      const dataRegionBytes = st.size - 8 - hdrLen;

      let tensorCount = 0;
      const offsetErrors: string[] = [];

      for (const [key, val] of Object.entries(parsed)) {
        if (key === "__metadata__") continue;
        tensorCount++;
        const offs = val?.data_offsets;
        if (!Array.isArray(offs) || offs.length !== 2) {
          offsetErrors.push(`${key}:MISSING_OFFSETS`);
          continue;
        }
        const [begin, end] = [Number(offs[0]), Number(offs[1])];
        if (!Number.isInteger(begin) || !Number.isInteger(end) || begin < 0 || end < begin || end > dataRegionBytes) {
          offsetErrors.push(`${key}:OUT_OF_BOUNDS_OFFSET`);
        }
      }

      const out = JSON.stringify(
        {
          file: modelFile,
          headerBytes: hdrLen,
          tensorCount,
          validOffsets: offsetErrors.length === 0,
          offsetErrors: offsetErrors.slice(0, 50),
          metadata: "[REDACTED]",
        },
        null,
        2,
      );
      return { content: [{ type: "text", text: out.slice(0, MAX_OUT_BYTES) }] };
    } finally {
      await fh.close();
    }
  });
}
