package hstsgrade

import (
	"encoding/json"
	"errors"
	"strconv"
	"strings"
)

const (
	maxInBytes  = 16384
	maxOutBytes = 16384
)

func GradeHstsPreloadReadiness(rawHeaders string) (string, error) {
	if len(rawHeaders) == 0 || len(rawHeaders) > maxInBytes {
		return "", errors.New("rawHeaders must be between 1 and 16384 bytes")
	}

	hdrs := make(map[string]string)
	for _, line := range strings.Split(rawHeaders, "\n") {
		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			continue
		}
		k := strings.ToLower(strings.TrimSpace(parts[0]))
		v := strings.TrimSpace(parts[1])
		if k == "cookie" || k == "set-cookie" || k == "authorization" || k == "x-api-key" {
			hdrs[k] = "[REDACTED]"
		} else {
			hdrs[k] = v
		}
	}

	var issues []string
	hsts, ok := hdrs["strict-transport-security"]
	maxAge := 0
	hasSub := false
	hasPreload := false

	if !ok {
		issues = append(issues, "MISSING_HSTS_HEADER")
	} else {
		for _, dir := range strings.Split(hsts, ";") {
			d := strings.ToLower(strings.TrimSpace(dir))
			switch {
			case strings.HasPrefix(d, "max-age="):
				n, err := strconv.Atoi(strings.TrimPrefix(d, "max-age="))
				if err == nil {
					maxAge = n
				}
			case d == "includesubdomains":
				hasSub = true
			case d == "preload":
				hasPreload = true
			}
		}
		if maxAge < 31536000 {
			issues = append(issues, "HSTS_MAX_AGE_LT_ONE_YEAR")
		}
		if !hasSub {
			issues = append(issues, "HSTS_MISSING_INCLUDESUBDOMAINS")
		}
	}

	if _, hasHpkp := hdrs["public-key-pins"]; hasHpkp {
		issues = append(issues, "DEPRECATED_HPKP_HEADER_PRESENT")
	}
	if _, hasEct := hdrs["expect-ct"]; hasEct {
		issues = append(issues, "OBSOLETE_EXPECT_CT_HEADER_PRESENT")
	}

	out, err := json.MarshalIndent(map[string]any{
		"preload_eligible":  ok && maxAge >= 31536000 && hasSub && hasPreload,
		"max_age":           maxAge,
		"issues":            issues,
		"sanitized_headers": hdrs,
	}, "", "  ")
	if err != nil {
		return "", err
	}
	if len(out) > maxOutBytes {
		return string(out[:maxOutBytes]), nil
	}
	return string(out), nil
}
