import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { X509Certificate } from "node:crypto";
import { lstat, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

const MAX_CHAIN_BYTES = 262_144;
const MAX_OUT_BYTES = 16_384;
const PRIV_RE = /-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----/g;
const CERT_BLOCK_RE = /-----BEGIN CERTIFICATE-----[\s\S]*?-----END CERTIFICATE-----/g;

const ChainSigVerifySchema = {
  chainPem: z.string().regex(/^[a-zA-Z0-9_.-]+\.pem$/),
};

export function registerX509ChainSignatureVerifier(server: McpServer, certDir = "/srv/sandbox/certs"): void {
  server.tool("verify_x509_chain_signatures", ChainSigVerifySchema, async ({ chainPem }) => {
    const canonDir = await realpath(certDir);
    const candidate = path.join(canonDir, chainPem);
    const st = await lstat(candidate);
    if (st.isSymbolicLink() || !st.isFile() || st.size > MAX_CHAIN_BYTES) {
      throw new Error("Chain PEM is symlinked, missing, or exceeds 256 KiB");
    }
    const resolved = await realpath(candidate);
    if (path.dirname(resolved) !== canonDir) {
      throw new Error("Chain PEM escaped sandbox confinement");
    }

    const raw = await readFile(resolved, { encoding: "utf8", signal: AbortSignal.timeout(2000) });
    const privateKeyRedacted = PRIV_RE.test(raw);
    const blocks = (raw.replace(PRIV_RE, "").match(CERT_BLOCK_RE) ?? []).slice(0, 10);
    if (blocks.length < 2) {
      throw new Error("Expected at least 2 certificates (leaf + issuer) in PEM chain");
    }

    const certs = blocks.map((b) => new X509Certificate(b));
    const links: Array<{ childIndex: number; subject: string; issuer: string; signatureValid: boolean; issuerIsCa: boolean }> = [];
    let allLinksValid = true;

    for (let i = 0; i < certs.length - 1; i++) {
      const child = certs[i];
      const parent = certs[i + 1];
      const sigOk = child.verify(parent.publicKey);
      if (!sigOk || !parent.ca) allLinksValid = false;
      links.push({
        childIndex: i,
        subject: child.subject,
        issuer: parent.subject,
        signatureValid: sigOk,
        issuerIsCa: parent.ca,
      });
    }

    const out = JSON.stringify(
      {
        chainFile: chainPem,
        certificateCount: certs.length,
        allChainSignaturesValid: allLinksValid,
        privateKeyDetectedAndRedacted: privateKeyRedacted,
        links,
      },
      null,
      2,
    );
    return { content: [{ type: "text", text: out.slice(0, MAX_OUT_BYTES) }] };
  });
}
